.workbench-body {
  --workbench-rail-width: clamp(5.4rem, 7vw, 6.35rem);
  --episode-replica-topbar-offset: max(0.55rem, calc(env(titlebar-area-height, 0px) + 0.35rem));
  --episode-replica-topbar-offset-compact: max(0.45rem, calc(env(titlebar-area-height, 0px) + 0.25rem));
  --episode-replica-layout-offset: max(2.2rem, calc(var(--episode-replica-topbar-offset) + 0.05rem));
  --episode-replica-left-width: minmax(0, 1fr);
  --episode-replica-center-width: 46.2rem;
  --episode-replica-right-width: 8.9rem;
