    radial-gradient(circle at 18% 12%, oklch(45% 0.14 292 / 0.2), transparent 26rem),
    radial-gradient(circle at 86% 4%, oklch(64% 0.14 205 / 0.12), transparent 22rem),
    var(--color-canvas, #0a0a0a);
  --theme-home-background:
    radial-gradient(circle at 53% -8%, oklch(82% 0.18 225 / 0.56), transparent 20rem),
    radial-gradient(circle at 16% 16%, oklch(62% 0.27 292 / 0.34), transparent 25rem),
    radial-gradient(circle at 82% 14%, oklch(73% 0.22 316 / 0.24), transparent 27rem),
    radial-gradient(circle at 58% 74%, oklch(76% 0.17 220 / 0.16), transparent 24rem),
    linear-gradient(135deg, oklch(8% 0.04 285), oklch(4.5% 0.035 258) 44%, oklch(7% 0.045 308));
  --theme-statusbar-button-background:
    radial-gradient(circle at 50% 0%, rgba(169, 141, 241, 0.18), transparent 62%),
    linear-gradient(180deg, rgba(154, 126, 228, 0.18), rgba(154, 126, 228, 0.1)),
    linear-gradient(180deg, oklch(18% 0.012 260 / 0.82), oklch(15% 0.012 255 / 0.84));
  --theme-statusbar-button-hover-background:
    radial-gradient(circle at 50% 0%, rgba(176, 148, 248, 0.24), transparent 62%),
    linear-gradient(180deg, rgba(166, 138, 236, 0.24), rgba(166, 138, 236, 0.12)),
    linear-gradient(180deg, oklch(21% 0.015 260 / 0.86), oklch(16% 0.015 255 / 0.88));
  --theme-statusbar-border: rgba(176, 146, 246, 0.18);
  --theme-statusbar-hover-border: rgba(194, 168, 255, 0.28);
  --theme-statusbar-shadow: rgba(46, 24, 92, 0.22);
  --theme-brand-gradient: linear-gradient(180deg, oklch(82% 0.15 325), oklch(68% 0.26 275));
