    radial-gradient(ellipse at 53% 3%, oklch(87% 0.16 221 / 0.34), transparent 28%),
    radial-gradient(ellipse at 23% 24%, oklch(62% 0.29 294 / 0.16), transparent 37%),
    radial-gradient(ellipse at 84% 30%, oklch(57% 0.26 281 / 0.14), transparent 40%);
