  --theme-panel-background-soft:
    linear-gradient(180deg, rgba(29, 31, 43, 0.88), rgba(15, 16, 25, 0.94));
  --theme-support-card-background:
    radial-gradient(circle at 50% 0%, var(--theme-accent-soft), transparent 10rem),
