  --theme-control-hover-background:
    linear-gradient(180deg, rgba(177, 150, 255, 0.14), rgba(255, 255, 255, 0.025)),
    rgba(30, 31, 44, 0.94);
  --theme-control-active-background:
    radial-gradient(circle at 18% 50%, rgba(183, 164, 255, 0.46), transparent 52%),
    linear-gradient(135deg, rgba(55, 48, 92, 0.98), rgba(22, 24, 36, 0.96));
  --theme-control-active-text: #ffffff;
  --theme-control-border: rgba(255, 255, 255, 0.08);
  --theme-control-hover-border: var(--theme-statusbar-hover-border);
  --theme-control-active-border: rgba(200, 184, 255, 0.56);
  --theme-accent-gradient: linear-gradient(90deg, oklch(61% 0.29 286), oklch(75% 0.18 230));
  --theme-accent-soft: rgba(154, 126, 228, 0.16);
  --theme-accent-strong: rgba(169, 141, 241, 0.72);
  --theme-input-background: rgba(26, 28, 38, 0.94);
  --theme-muted-background: rgba(255, 255, 255, 0.04);
  --director-bg-rgb: 7 8 13;
  --director-surface-rgb: 25 27 38;
  --director-surface-hover-rgb: 30 31 44;
  --director-panel-rgb: 21 22 32;
  --director-field-rgb: 26 28 38;
  --director-border-rgb: 63 59 82;
  --director-text-rgb: 255 255 255;
  --director-text-muted-rgb: 166 168 188;
  --director-text-dim-rgb: 100 102 125;
  --director-accent-rgb: 194 143 255;
  --director-accent-hover-rgb: 218 184 255;
  --director-overlay-rgb: 7 8 13;
  --theme-rail-background:
    linear-gradient(180deg, rgba(31, 33, 45, 0.94), rgba(12, 13, 21, 0.98));
  height: 100dvh;
  min-height: 100dvh;
  overflow-x: hidden;
  overflow-y: hidden;
  background: var(--theme-body-background);
  letter-spacing: 0;
}

.app-login-modal {
  --login-modal-text-primary: rgba(255, 255, 255, 0.94);
  --login-modal-text-muted: rgba(226, 230, 244, 0.7);
  --login-modal-text-dim: rgba(190, 198, 220, 0.5);
  --bg-void: var(--theme-app-background);
  --glow-tint: var(--theme-accent-strong);
  --glow-tint-soft: var(--theme-accent-soft);
  --border-sharp: var(--theme-control-active-border);
  --text-primary: var(--login-modal-text-primary);
  --text-muted: var(--login-modal-text-muted);
  --text-dim: var(--login-modal-text-dim);
  --surface-glass: var(--theme-panel-background);
  --surface-raised: var(--theme-panel-background-soft);
  --line-subtle: var(--theme-control-border);
  --line-sharp: var(--theme-control-hover-border);
  --line-glow: var(--theme-control-active-border);
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: grid;
  place-items: center;
  padding: clamp(1rem, 3vw, 2rem);
  color: var(--text-primary);
  color-scheme: dark;
}

.app-login-modal-backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  background: transparent;
}

.app-login-modal-panel {
  position: relative;
  width: min(31rem, calc(100vw - 2rem));
  max-height: calc(100dvh - 2rem);
  overflow: hidden;
  border: 1px solid var(--theme-control-active-border);
  border-radius: 1.5rem;
  background:
    radial-gradient(circle at 50% 0%, var(--theme-accent-soft), transparent 18rem),
    var(--theme-panel-background);
  box-shadow:
    0 1.5rem 5rem rgba(0, 0, 0, 0.48),
    0 0 0 1px rgba(255, 255, 255, 0.06) inset;
}

.app-login-modal-panel > .auth-panel {
  width: 100%;
  min-height: 0;
  max-height: calc(100dvh - 2rem);
  border-radius: inherit;
  padding: 2.4rem 2rem 1.75rem;
  overflow: auto;
  background:
    radial-gradient(circle at 50% 0%, var(--theme-accent-soft), transparent 17rem),
    transparent;
}

.app-login-modal-close {
  position: absolute;
  top: 0.85rem;
  right: 0.85rem;
  z-index: 2;
  display: grid;
  width: 2.2rem;
  height: 2.2rem;
  min-height: 0;
  padding: 0;
  place-items: center;
  border: 1px solid var(--theme-control-border);
  border-radius: 999px;
  color: var(--text-primary);
  background: var(--theme-control-background);
  font-size: 1.15rem;
  line-height: 1;
  cursor: pointer;
}

.workbench-body .app-login-modal .primary-action {
  border-color: transparent;
  background: var(--theme-accent-gradient);
  color: var(--theme-control-active-text);
  box-shadow:
    0 0.85rem 1.8rem var(--theme-accent-soft),
    inset 0 1px 0 rgba(255, 255, 255, 0.14);
}

.workbench-body .app-login-modal .primary-action:hover {
  background: var(--theme-accent-gradient);
  color: var(--theme-control-active-text);
  box-shadow:
    0 1rem 2rem var(--theme-accent-soft),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.workbench-body .app-login-modal .primary-action.is-disabled,
.workbench-body .app-login-modal .primary-action[aria-disabled="true"] {
  background: var(--theme-control-active-background);
  color: color-mix(in srgb, var(--theme-control-active-text) 64%, transparent);
  box-shadow: none;
  opacity: 0.68;
}

.workbench-body .app-login-modal .secondary-action,
.workbench-body .app-login-modal .social-btn,
.workbench-body .app-login-modal .agreement-modal-close {
  border-color: var(--theme-control-border);
  background: var(--theme-control-background);
  color: var(--text-muted);
}

.workbench-body .app-login-modal .secondary-action:hover,
.workbench-body .app-login-modal .social-btn:hover,
.workbench-body .app-login-modal .agreement-modal-close:hover,
.workbench-body .app-login-modal .app-login-modal-close:hover {
  border-color: var(--theme-control-hover-border);
  background: var(--theme-control-hover-background);
  color: var(--text-primary);
}

.workbench-body .app-login-modal .agreement-modal-backdrop {
  background: rgba(0, 0, 0, 0.42);
}

.workbench-body .app-login-modal .agreement-modal-panel {
  border-color: var(--theme-control-border);
  background: var(--theme-panel-background);
  box-shadow: 0 1.4rem 4rem rgba(0, 0, 0, 0.42);
}

.workbench-body .global-toast {
  z-index: 10020;
}

@media (max-width: 640px) {
  .app-login-modal {
    padding: 0.75rem;
  }

  .app-login-modal-panel {
    width: min(100%, 30rem);
    max-height: calc(100dvh - 1.5rem);
    border-radius: 1.15rem;
  }

  .app-login-modal-panel > .auth-panel {
    max-height: calc(100dvh - 1.5rem);
    padding: 2.2rem 1.45rem 1.45rem;
  }
}

