  overflow-y: auto;
  background: #f4f7fb;
}

.workbench-body.community-window-body::after {
  display: none;
  opacity: 0;
}

.creator-app {
  height: 100dvh;
  min-height: 100dvh;
  overflow: hidden;
}

.community-window-body .creator-app {
  height: auto;
  min-height: 100dvh;
  overflow: visible;
}

.workbench-loading,
.workbench-fatal {
  position: relative;
  z-index: 2;
  display: grid;
  min-height: 100dvh;
  place-items: center;
  padding: 2rem;
  color: var(--text-muted);
}

.workbench-fatal {
  align-content: center;
  gap: 1rem;
}

.workbench-fatal h1 {
  margin: 0;
  max-width: none;
  font-size: 1.4rem;
  letter-spacing: 0;
}

.workbench-fatal a {
  color: var(--glow-tint);
}

.workbench-scroll-surface[data-scroll-surface="community"] {
  background: #f4f7fb;
}

.workbench-scroll-surface[data-scroll-surface="media-library"] {
  background: #f7fafc;
}

.production-community-window {
  min-height: 100dvh;
  background: #f4f7fb;
}

.production-media-library-window {
  background:
    radial-gradient(circle at top right, rgba(26, 114, 255, .08), transparent 24rem),
    #f7fafc;
}

.community-window-header {
  position: sticky;
  top: 0;
  z-index: 70;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 4.4rem;
  padding: .7rem clamp(1.25rem, 2.2vw, 2.5rem);
  border-bottom: 1px solid rgba(213, 223, 238, .88);
  background: rgba(255, 255, 255, .94);
  box-shadow: 0 8px 28px rgba(38, 50, 74, .05);
  backdrop-filter: blur(16px);
}

.community-window-brand {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: .7rem;
  min-width: 0;
  color: #111827;
}

.community-window-brand div {
  display: grid;
  gap: .16rem;
}

.community-window-brand strong {
  color: #111827;
  font-size: 1.35rem;
  font-weight: 900;
  letter-spacing: 0;
}

.community-window-brand span:not(.statusbar-n-mark) {
  color: #60728d;
  font-size: .78rem;
  font-weight: 800;
}

.community-window-title {
  position: absolute;
  left: 50%;
  max-width: min(32rem, calc(100% - 18rem));
  transform: translate(-50%, -50%);
  overflow: hidden;
  color: #172033;
  font-size: 1.05rem;
  font-weight: 900;
  letter-spacing: 0;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.community-window-actions {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: .75rem;
}

.community-window-account {
  position: relative;
}

.community-window-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.7rem;
  height: 2.7rem;
  border: 1px solid #dbe6f5;
  border-radius: 999px;
  padding: 0;
  background: linear-gradient(135deg, #eef4ff, #f5f0ff);
  color: #315a9d;
  font-size: .86rem;
  font-weight: 900;
}

.community-window-avatar span {
  display: block;
  max-width: 1.8rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.community-window-account-popover {
  position: absolute;
  top: calc(100% + .55rem);
  right: 0;
  z-index: 6;
  display: grid;
  gap: .22rem;
  min-width: 12rem;
  padding: .8rem .9rem;
  border: 1px solid #dbe6f5;
  border-radius: 12px;
  background: rgba(255, 255, 255, .98);
  box-shadow: 0 18px 42px rgba(36, 52, 78, .14);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-.2rem);
  transition: opacity 140ms ease, transform 140ms ease;
}

.community-window-account:hover .community-window-account-popover,
.community-window-account:focus-within .community-window-account-popover {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.community-window-account-popover small {
  color: #60728d;
  font-size: .72rem;
  font-weight: 800;
}

.community-window-account-popover strong {
  color: #172033;
  font-size: .92rem;
  font-weight: 900;
}

.community-window-account-popover span {
  color: #60728d;
  font-size: .8rem;
  line-height: 1.45;
}

.community-window-back {
