  gap: 1rem;
  align-content: start;
  min-height: calc(100dvh - 6.5rem);
  padding: clamp(1rem, 1.8vw, 2rem) clamp(1.25rem, 2.2vw, 2.5rem) clamp(1.25rem, 2.2vw, 2.5rem);
  color: #172033;
  background: #f4f7fb;
}

.community-overview {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: .8rem;
  align-items: center;
  border: 1px solid #dfe7f1;
  border-radius: 8px;
  padding: .7rem .85rem;
  background: #ffffff;
  box-shadow: 0 14px 38px rgba(42, 57, 82, .06);
}

.community-overview > div {
  display: grid;
  gap: .25rem;
  min-width: 0;
}

.community-overview span,
.community-section-head span {
  color: #60728d;
  font-size: .74rem;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.community-overview strong {
  color: #111827;
  font-size: .95rem;
  line-height: 1.45;
}

.community-overview dl {
