  gap: .15rem;
  min-height: 3rem;
  align-content: center;
  border: 1px solid #e2e9f3;
  border-radius: 8px;
  padding: .38rem .62rem;
  background: #f8fafc;
}

.community-overview dt {
  color: #718096;
  font-size: .76rem;
  font-weight: 800;
}

.community-overview dd {
  margin: 0;
  color: #172033;
  font-size: 1.08rem;
  font-weight: 950;
  line-height: 1;
}

.community-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(16rem, 22rem);
  gap: 1rem;
  align-items: stretch;
  margin-bottom: 1rem;
}

.community-hero,
.community-column {
  border: 1px solid #dfe7f1;
  border-radius: 8px;
  background: rgba(255, 255, 255, .98);
  box-shadow: 0 14px 38px rgba(42, 57, 82, .06);
}

.community-hero {
  padding: clamp(1.25rem, 2.4vw, 2rem);
}

.community-eyebrow {
  margin: 0 0 .65rem;
  color: #486385;
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.community-hero h1 {
  margin: 0;
  color: #0f172a;
  font-size: clamp(2rem, 4vw, 4rem);
  line-height: 1;
  letter-spacing: 0;
}

.community-hero p {
  max-width: 52rem;
  margin: 1rem 0 0;
  color: #52627a;
  font-size: 1rem;
  line-height: 1.8;
}

.community-hero-panel {
  display: grid;
  align-content: center;
  gap: .45rem;
  min-height: 9rem;
  padding: 1rem;
  border: 1px solid #dbe6f5;
  border-radius: 8px;
  background: #f4f8ff;
}

.community-hero-panel span,
.community-hero-panel small {
  color: #60728d;
}

.community-hero-panel strong {
  color: #111827;
  font-size: 1.4rem;
}

.community-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(22rem, .92fr);
  gap: 1.1rem;
  align-items: start;
}

.personal-media-page {
  display: grid;
  gap: 1rem;
}

.personal-media-hero {
  margin-bottom: 0;
}

.personal-media-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: .9rem;
}

.personal-media-stat-card,
.personal-media-panel,
.personal-media-row {
  border: 1px solid #dfe7f1;
  border-radius: 8px;
  background: rgba(255, 255, 255, .96);
  box-shadow: 0 18px 50px rgba(36, 52, 78, .08);
}

.personal-media-stat-card {
  display: grid;
  gap: .4rem;
  padding: 1rem 1.1rem;
}

.personal-media-stat-card small,
.personal-media-stat-card span {
  color: #60728d;
}

.personal-media-stat-card strong {
  color: #111827;
  font-size: 1.6rem;
}

.personal-media-panel {
  display: grid;
  gap: 1rem;
  padding: 1rem;
}

.personal-media-toolbar {
  display: grid;
  grid-template-columns: minmax(16rem, 1fr) auto auto;
  gap: .8rem;
  align-items: end;
}

.personal-media-search {
  display: grid;
  gap: .4rem;
  color: #486385;
  font-weight: 700;
  font-size: .82rem;
}

.personal-media-search input {
  min-height: 2.9rem;
  border: 1px solid #dbe6f5;
  border-radius: 8px;
  padding: 0 .95rem;
  background: #fff;
  color: #172033;
}

.personal-media-chip-group {
  display: flex;
  flex-wrap: wrap;
  gap: .55rem;
}

.personal-media-chip {
  min-height: 2.5rem;
  border: 1px solid #d7e4f5;
  border-radius: 999px;
  padding: 0 .9rem;
  background: #fff;
  color: #486385;
  font-weight: 700;
}

.personal-media-chip.is-active {
  border-color: #1f5fd0;
  background: #1f5fd0;
  color: #fff;
}

.personal-media-feedback {
  border-radius: 8px;
  padding: .85rem 1rem;
  font-weight: 700;
}

.personal-media-feedback.loading {
  background: #edf5ff;
  color: #1f5fd0;
}

.personal-media-feedback.error {
  background: #fff1f4;
  color: #e11d48;
}

.personal-media-list {
  display: grid;
  gap: .8rem;
}

.personal-media-row {
  display: grid;
  grid-template-columns: 7.5rem minmax(0, 1fr) auto;
  gap: 1rem;
  align-items: center;
  padding: .9rem;
}

.personal-media-preview {
  position: relative;
  display: grid;
  place-items: center;
  overflow: hidden;
  aspect-ratio: 4 / 3;
  border-radius: 8px;
  background: linear-gradient(135deg, #e8eef8, #f8fbff);
  color: #486385;
  font-weight: 800;
}

.personal-media-preview img,
.personal-media-preview video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.personal-media-preview i {
  position: absolute;
  inset: auto auto .55rem .55rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  background: rgba(15, 23, 42, .72);
  color: #fff;
  font-style: normal;
  font-size: .8rem;
}

.personal-media-meta {
  display: grid;
  gap: .45rem;
  min-width: 0;
}

.personal-media-title-line {
  display: flex;
  align-items: center;
  gap: .75rem;
  min-width: 0;
}

.personal-media-title-line strong {
  min-width: 0;
  color: #111827;
  font-size: 1rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.personal-media-kind {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 3.3rem;
  min-height: 1.7rem;
  border-radius: 999px;
  padding: 0 .65rem;
  font-size: .76rem;
  font-weight: 800;
}

.personal-media-kind.image {
  background: #edf5ff;
  color: #1f5fd0;
}

.personal-media-kind.video {
  background: #fff2e8;
  color: #d97706;
}

.personal-media-subline {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem 1rem;
  color: #60728d;
  font-size: .88rem;
}

.personal-media-actions {
  display: flex;
  gap: .7rem;
  align-items: center;
}

.personal-media-actions a {
  color: #1f5fd0;
  font-weight: 800;
  text-decoration: none;
}

.personal-media-pagination {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: .8rem;
  color: #60728d;
  font-weight: 700;
}

.personal-media-pagination button {
  min-height: 2.35rem;
  border: 1px solid #dbe6f5;
  border-radius: 8px;
  padding: 0 .9rem;
  background: #fff;
  color: #172033;
  font-weight: 800;
}

.community-prompt-studio {
  display: grid;
  gap: 1rem;
  margin-bottom: 1rem;
  padding: 1rem;
  border: 1px solid #dfe7f1;
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, .92), rgba(247, 250, 252, .96)),
    repeating-linear-gradient(135deg, rgba(31, 111, 255, .06) 0 1px, transparent 1px 12px);
  box-shadow: 0 18px 50px rgba(36, 52, 78, .07);
}

.community-studio-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(16rem, 24rem);
  gap: 1rem;
  align-items: end;
}

.community-studio-head h2 {
  margin: 0;
  color: #111827;
  font-size: clamp(1.45rem, 2.4vw, 2.4rem);
  letter-spacing: 0;
}

.community-studio-head p {
  margin: .45rem 0 0;
  color: #52627a;
  line-height: 1.75;
}

.community-studio-rule {
  display: grid;
  gap: .35rem;
  padding: 1rem;
  border: 1px solid #d7e4f5;
  border-radius: 8px;
  background: #fff;
  color: #60728d;
}

.community-studio-rule strong {
  color: #111827;
  font-size: 1.08rem;
}

.community-insight-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: .9rem;
}

.community-insight-card {
  display: grid;
  gap: .8rem;
  min-height: 20rem;
  padding: 1rem;
  border: 1px solid #dce7f5;
  border-radius: 8px;
  background: #fff;
