}

.community-insight-card h3 {
  margin: 0;
  color: #0f172a;
  font-size: 1.1rem;
  letter-spacing: 0;
}

.community-insight-card p {
  margin: 0;
  color: #52627a;
  line-height: 1.75;
}

.community-insight-topline,
.community-insight-card footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .75rem;
  color: #64748b;
  font-size: .8rem;
}

.community-insight-topline strong {
  color: #1f5fd0;
}

.community-prompt-snippet {
  display: grid;
  gap: .45rem;
  margin-top: auto;
  padding: .8rem;
  border: 1px solid #d9e5f4;
  border-radius: 8px;
  background: #f8fbff;
}

.community-prompt-snippet span {
  color: #64748b;
  font-size: .76rem;
  font-weight: 800;
}

.community-prompt-snippet code {
  color: #172033;
  font-family: "Microsoft YaHei UI", "PingFang SC", sans-serif;
  font-size: .88rem;
  line-height: 1.65;
  white-space: normal;
}

.community-insight-card footer div {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: .35rem;
}

.community-insight-card footer em {
  padding: .18rem .45rem;
  border-radius: 999px;
  background: #eef4ff;
  color: #315a9d;
  font-style: normal;
  font-weight: 800;
}

.community-column {
  display: grid;
  gap: .9rem;
  padding: 1rem;
}

.community-feature-column {
  position: sticky;
  top: 5.4rem;
}

.community-section-head h2,
.community-post h3,
.community-feature-card h3 {
  margin: 0;
  color: #111827;
  letter-spacing: 0;
}

.community-section-head h2 {
  margin-top: .2rem;
  font-size: 1.35rem;
  line-height: 1.2;
}

.community-section-head p,
.community-feature-card p,
.community-post p {
  color: #52627a;
  line-height: 1.7;
}

.community-section-head p {
  margin: .35rem 0 0;
}

.community-form {
  display: grid;
  gap: .8rem;
  padding: 1rem;
  border: 1px solid #e1e8f2;
  border-radius: 8px;
  background: #fbfdff;
}

.community-dialog-form {
  padding: 0;
  border: 0;
  background: transparent;
}

.community-form label {
  display: grid;
  gap: .4rem;
  color: #334155;
  font-size: .88rem;
  font-weight: 700;
}

.community-form input,
.community-form select,
.community-form textarea {
  width: 100%;
  border: 1px solid #d9e3ee;
  border-radius: 8px;
  padding: .8rem .9rem;
  background: #fff;
  color: #111827;
  outline: none;
}

.community-form textarea {
  resize: vertical;
}

.community-form input:focus,
.community-form select:focus,
.community-form textarea:focus {
  border-color: #3670ff;
  box-shadow: 0 0 0 3px rgba(54, 112, 255, .14);
}

.community-primary {
  min-height: 2.75rem;
  border: 0;
  border-radius: 8px;
  background: #1f6fff;
  color: #fff;
  font-weight: 800;
}

.community-feed,
.community-feature-list {
  display: grid;
  gap: .75rem;
}

.community-post,
.community-feature-card,
.community-empty {
  border: 1px solid #e1e8f2;
  border-radius: 8px;
  background: #fff;
  padding: 1rem;
}

.community-post {
  display: grid;
  gap: .82rem;
  box-shadow: 0 10px 28px rgba(42, 57, 82, .045);
}

.community-post-head {
  display: grid;
  gap: .5rem;
}

.community-post-head h3 {
  min-width: 0;
  font-size: 1.08rem;
  line-height: 1.35;
}

.community-post p {
  margin: 0;
  font-size: .96rem;
}

.community-post footer {
  display: flex;
  justify-content: space-between;
  gap: .75rem;
  border-top: 1px solid #edf2f7;
  padding-top: .72rem;
  color: #718096;
  font-size: .82rem;
  font-weight: 700;
}

.community-post-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: center;
  gap: .65rem;
  padding: 0;
}

.community-social-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .45rem;
  min-height: 2.65rem;
  border: 1px solid #e4ebf5;
  border-radius: 8px;
  padding: 0 .85rem;
  background: #f8fbff;
  color: #111827;
  font-size: .9rem;
  font-weight: 800;
  text-align: center;
}

.community-social-action svg {
  width: 1.18rem;
  height: 1.18rem;
  fill: currentColor;
  stroke: currentColor;
  stroke-width: 0;
}

.community-social-action.comment svg {
  color: #3670ff;
}

.community-social-action.like svg {
  color: #ff6687;
}

.community-social-action:hover {
  border-color: #cfe0ff;
  background: #eef5ff;
}

.community-social-action.liked span {
  color: #1d4ed8;
}

.community-comments {
  display: grid;
  grid-template-columns: 1fr;
  gap: .6rem;
  padding: .75rem;
  border: 1px solid #e9eef6;
  border-radius: 8px;
  background: #f9fbfe;
}

.community-comment {
  display: grid;
  gap: .45rem;
  color: #52627a;
  font-size: .84rem;
}

.community-comment-main,
.community-reply {
  display: grid;
  gap: .3rem;
}

.community-comment-line {
  display: flex;
  flex-wrap: wrap;
  gap: .45rem;
  align-items: baseline;
}

.community-comment-meta {
  display: flex;
  align-items: center;
  gap: .5rem;
}

.community-comment strong {
  flex: 0 0 auto;
  color: #172033;
}

.community-comment-line span {
  min-width: 0;
  color: #52627a;
  word-break: break-word;
}

.community-comment button {
  justify-self: start;
  min-height: 1.6rem;
  border: 0;
  border-radius: 999px;
  padding: 0 .55rem;
  background: #eef4ff;
  color: #315a9d;
  font-size: .76rem;
  font-weight: 800;
}

.community-comment small,
.community-comment-empty {
  color: #8a98ad;
  font-size: .78rem;
}

.community-replies {
  display: grid;
  gap: .45rem;
  margin-left: .85rem;
  padding-left: .75rem;
  border-left: 2px solid #dbe6f5;
}

.community-reply {
  color: #52627a;
  font-size: .82rem;
}

.community-comment-more {
  color: #8a98ad;
  font-size: 1rem;
  font-weight: 800;
  line-height: 1;
}

.community-comment-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: .5rem;
}

.community-comment-form.reply {
  margin-left: .85rem;
}

.community-comment-form input {
  min-height: 2.45rem;
  border: 1px solid #dbe6f5;
  border-radius: 8px;
  padding: 0 .8rem;
  background: #fff;
  color: #172033;
}

.community-comment-form button {
  min-height: 2.45rem;
  border: 0;
  border-radius: 8px;
  padding: 0 .85rem;
  background: #1f6fff;
  color: #fff;
  font-weight: 800;
}

.community-tag {
  display: inline-flex;
  align-items: center;
  justify-self: start;
  min-height: 1.55rem;
  padding: 0 .62rem;
  border-radius: 999px;
  background: #eef4ff;
  color: #315a9d;
  font-size: .76rem;
  font-weight: 800;
}

.community-feature-card {
  display: grid;
  grid-template-columns: 4.8rem minmax(0, 1fr);
  gap: .85rem;
  align-items: stretch;
  box-shadow: 0 10px 28px rgba(42, 57, 82, .04);
}

.community-vote {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 5rem;
  border: 1px solid #cfe0ff;
  border-radius: 8px;
  background: linear-gradient(180deg, #f4f8ff 0%, #edf4ff 100%);
  color: #1d4ed8;
  font-weight: 900;
}

.community-vote.voted {
  border-color: #b9d1ff;
  background: #e6f0ff;
  color: #1747b8;
}

.community-vote strong {
  font-size: 1.45rem;
  line-height: 1;
}

.community-vote span,
.community-feature-card small {
  font-size: .78rem;
}

.community-vote span {
  white-space: nowrap;
}

.community-feature-card p,
.community-feature-card small {
  margin: .35rem 0 0;
  color: #64748b;
}

.community-feature-card h3 {
  font-size: 1.02rem;
  line-height: 1.35;
}

.community-feature-card p {
  font-size: .92rem;
}

.community-empty {
  display: grid;
  gap: .4rem;
  color: #64748b;
  text-align: center;
}

.community-empty strong {
  color: #172033;
}

.community-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .75rem;
  padding: .35rem 0 0;
  color: #64748b;
  font-size: .86rem;
  font-weight: 800;
}

.community-pagination button {
  min-height: 2.35rem;
  border: 1px solid #dbe6f5;
  border-radius: 8px;
  padding: 0 .85rem;
  background: #fff;
  color: #1d4ed8;
  font-weight: 800;
}

.community-pagination button:disabled {
  color: #94a3b8;
  cursor: not-allowed;
  opacity: .55;
}

.community-fab-wrap {
  position: fixed;
  right: clamp(1.25rem, 3vw, 2.6rem);
  bottom: clamp(1.25rem, 3vw, 2.4rem);
  z-index: 80;
  display: grid;
  justify-items: end;
  gap: .75rem;
}

.community-fab-menu {
  display: grid;
  width: min(22rem, calc(100vw - 2rem));
  gap: .55rem;
  padding: .7rem;
  border: 1px solid #d8e4f2;
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 22px 60px rgba(15, 23, 42, .18);
  opacity: 0;
  pointer-events: none;
  transform: translateY(.45rem) scale(.98);
  transform-origin: bottom right;
  transition: opacity 140ms ease, transform 140ms ease;
}

.community-fab-wrap:hover .community-fab-menu,
.community-fab-wrap:focus-within .community-fab-menu {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0) scale(1);
}

.community-fab-menu button {
  display: grid;
  gap: .25rem;
  min-height: 4.2rem;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: .85rem .95rem;
  background: #f8fbff;
  color: #52627a;
  text-align: left;
}

.community-fab-menu button:hover {
  border-color: #cfe0ff;
  background: #eef5ff;
}

.community-fab-menu strong {
  color: #111827;
  font-size: .98rem;
}

.community-fab-menu span {
  font-size: .82rem;
  line-height: 1.55;
}

.community-fab {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 4.05rem;
  height: 4.05rem;
  border: 1px solid rgba(31, 111, 255, .22);
  border-radius: 50%;
