  letter-spacing: 0;
}

.community-modal-head span {
  display: block;
  margin-top: .45rem;
  color: #60728d;
  line-height: 1.65;
}

.community-modal-close {
  position: relative;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 2.35rem;
  height: 2.35rem;
  border: 1px solid #dbe6f5;
  border-radius: 50%;
  background: #f8fbff;
  color: #52627a;
  font-size: 0;
  line-height: 0;
}

.community-modal-close::before,
.community-modal-close::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 1rem;
  height: 2px;
  border-radius: 999px;
  background: currentColor;
  transform-origin: center;
}

.community-modal-close::before {
  transform: translate(-50%, -50%) rotate(45deg);
}

.community-modal-close::after {
  transform: translate(-50%, -50%) rotate(-45deg);
