  gap: 0.3rem;
}

.account-settings-security-row strong {
  font-size: 0.98rem;
}

.account-settings-security-row span {
  color: oklch(100% 0 0 / 0.64);
  font-size: 0.84rem;
  line-height: 1.5;
}

.account-settings-password-grid {
  display: grid;
  gap: 0.8rem;
}

.account-settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 0.85rem 0;
