  transition: transform 160ms ease;
}

.account-settings-toggle-row.is-on .account-settings-toggle {
  background: linear-gradient(120deg, oklch(68% 0.22 286 / 0.92), oklch(78% 0.18 220 / 0.88));
}

.account-settings-toggle-row.is-on .account-settings-toggle i {
  transform: translateX(1.25rem);
}

.account-settings-footer {
  align-items: center;
  justify-content: flex-end;
  padding: 0.95rem 1.35rem 1.2rem;
  border-top: 1px solid oklch(100% 0 0 / 0.06);
  background: oklch(8% 0.016 252 / 0.86);
}

.account-settings-footer-copy {
  display: grid;
  gap: 0.22rem;
}

.account-settings-footer-copy strong {
  font-size: 0.92rem;
}

.account-settings-footer-copy span {
  color: oklch(100% 0 0 / 0.62);
  font-size: 0.8rem;
  line-height: 1.45;
}

.account-settings-footer-actions {
  display: flex;
