  gap: 0.7rem;
}

.account-settings-footer-actions button {
  min-height: 2.85rem;
  padding: 0 1.15rem;
  border-radius: 1rem;
  font-size: 0.88rem;
  font-weight: 800;
}

.account-settings-footer-actions .ghost {
  border: 1px solid oklch(100% 0 0 / 0.08);
  background: oklch(100% 0 0 / 0.04);
