  .account-invite-link-box button {
    width: 100%;
  }
}

.account-popover-card {
  display: grid;
  gap: 0.45rem;
  margin-bottom: 0.35rem;
  padding: 0.95rem 1rem;
  border-radius: 0.8rem;
  background:
    linear-gradient(135deg, oklch(100% 0 0 / 0.1), oklch(70% 0.16 305 / 0.16)),
