}

.popover-menu-item {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  width: 100%;
  min-height: 2.55rem;
  padding: 0 0.7rem;
  border: 0;
  border-radius: 0.55rem;
  background: transparent;
  color: oklch(100% 0 0 / 0.76);
  font: inherit;
  font-size: 0.9rem;
  font-weight: 700;
