}

.primary-action.compact,
.secondary-action.compact {
  padding: 0.72rem 1rem;
}

.home-hero {
  position: relative;
  height: 100dvh;
  overflow: hidden;
  border-left: 1px solid oklch(100% 0 0 / 0.04);
  --home-pointer-x: 50%;
  --home-pointer-y: 46%;
  background: var(--theme-home-background);
  isolation: isolate;
}

.home-hero::before {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent 0 14%, oklch(72% 0.16 224 / 0.06) 14.08% 14.16%, transparent 14.32% 36%, oklch(72% 0.16 224 / 0.05) 36.08% 36.16%, transparent 36.32% 64%, oklch(72% 0.16 224 / 0.05) 64.08% 64.16%, transparent 64.32% 86%, oklch(72% 0.16 224 / 0.06) 86.08% 86.16%, transparent 86.32% 100%),
    linear-gradient(180deg, oklch(100% 0 0 / 0.032) 0 1px, transparent 1px 100%);
  background-size: 100% 100%, 100% 5.5rem;
  mask-image: radial-gradient(circle at 50% 38%, black 0 42%, transparent 78%);
  mix-blend-mode: screen;
  content: "";
}

.home-liquid-ether {
  position: absolute;
  inset: -8%;
  z-index: 0;
  opacity: 1;
  pointer-events: none;
  filter: saturate(1.42) contrast(1.12) blur(0.16px);
}

.home-liquid-ether::before {
  position: absolute;
  inset: 4% 9% 16%;
  background: var(--theme-ether-glow);
  filter: blur(1.25rem);
  mix-blend-mode: screen;
  content: "";
}

.home-cinematic-sky,
.home-lightfall-field,
.home-cursor-aura {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.home-cinematic-sky {
  z-index: 1;
  overflow: hidden;
  opacity: 0.94;
}

.home-starfield-layer,
.home-scanline-layer {
  position: absolute;
  inset: -12%;
  display: block;
}

.home-starfield-layer {
  background-image:
    radial-gradient(circle, oklch(100% 0 0 / 0.7) 0 1px, transparent 1.7px),
    radial-gradient(circle, oklch(86% 0.12 235 / 0.46) 0 1px, transparent 1.6px);
  background-position: 0 0, 3.8rem 2.4rem;
  background-size: 7.5rem 7.5rem, 11rem 11rem;
  mask-image: radial-gradient(circle at 50% 44%, black 0 44%, transparent 76%);
  animation: homeStarDrift 24s linear infinite;
}

.home-starfield-layer.layer-two {
  opacity: 0.42;
  transform: scale(1.18) rotate(8deg);
  animation-duration: 38s;
  animation-direction: reverse;
}

.home-scanline-layer {
  opacity: 0.14;
  background:
    linear-gradient(90deg, transparent, oklch(76% 0.18 226 / 0.14), transparent),
    repeating-linear-gradient(90deg, transparent 0 6.4rem, oklch(100% 0 0 / 0.055) 6.48rem, transparent 6.58rem);
  transform: translateY(8%);
  mask-image: linear-gradient(90deg, transparent, black 26%, black 74%, transparent);
}

.home-lightfall-field {
  z-index: 3;
  inset: -12% -7% -6%;
  overflow: hidden;
  opacity: 0.98;
  mix-blend-mode: screen;
  mask-image:
    radial-gradient(circle at 52% 34%, black 0 58%, transparent 86%),
    linear-gradient(90deg, transparent, black 7%, black 93%, transparent);
}

.home-lightfall-field::before {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: var(--theme-lightfall-glow);
  filter: blur(0.4rem);
  opacity: 0.82;
  content: "";
}

.home-lightfall-canvas {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: block;
  width: 100%;
  height: 100%;
}

.home-lightfall-field[data-lightfall-state="failed"] {
  background:
    radial-gradient(ellipse at 53% 6%, oklch(84% 0.18 224 / 0.35), transparent 28%),
    linear-gradient(110deg, transparent 0 17%, oklch(92% 0.08 231 / 0.28) 17.2% 17.34%, transparent 17.6% 44%, oklch(84% 0.15 292 / 0.24) 44.1% 44.25%, transparent 44.5% 69%, oklch(94% 0.06 230 / 0.24) 69.1% 69.24%, transparent 69.5% 100%);
}

.home-cursor-aura {
  z-index: 4;
  opacity: 0.82;
  background: var(--theme-cursor-aura);
  mix-blend-mode: screen;
  transition: background-position 160ms ease-out;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  background:
    radial-gradient(circle at var(--home-pointer-x) var(--home-pointer-y), transparent 0, transparent 8rem, oklch(0% 0 0 / 0.08) 27rem),
    radial-gradient(circle at 52% 42%, transparent 0, transparent 12rem, oklch(0% 0 0 / 0.28) 35rem),
    linear-gradient(90deg, oklch(0% 0 0 / 0.46), transparent 26%, transparent 70%, oklch(0% 0 0 / 0.46)),
    linear-gradient(180deg, oklch(0% 0 0 / 0.08), oklch(0% 0 0 / 0.68));
}

.hero-content {
