  font-size: clamp(0.92rem, 1.5vw, 1.08rem);
  font-weight: 650;
  line-height: 1.75;
  text-shadow: 0 0.18rem 1rem oklch(0% 0 0 / 0.28);
}

.hero-value-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(1rem, 3vw, 2.5rem);
