  min-height: 0;
  overflow: hidden;
}

.workbench-main.tools-canvas-detail-mode .global-statusbar {
  position: absolute;
  top: 0.9rem;
  left: 0.45rem;
  right: 0.55rem;
}

.workbench-main.tools-canvas-list-mode {
  grid-template-rows: auto minmax(0, 1fr);
