.canvas-project-search input::placeholder {
  color: rgba(255, 255, 255, 0.42);
}

.canvas-project-card-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  grid-template-rows: repeat(3, minmax(0, 1fr));
  grid-auto-rows: minmax(0, 1fr);
  flex: 1 1 auto;
  min-height: 0;
  align-content: stretch;
  gap: clamp(0.45rem, 0.58vw, 0.68rem);
}

.canvas-project-empty {
  grid-column: 1 / -1;
  align-self: center;
  justify-self: center;
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.9rem;
  font-weight: 750;
}

.new-canvas-workbench-host,
.new-canvas-root {
  position: relative;
  width: 100%;
  min-height: 100%;
}

.new-canvas-loading-skeleton {
  display: grid;
  grid-template-columns: 4rem minmax(0, 1fr) minmax(12rem, 18rem);
  gap: 0.75rem;
  width: 100%;
  min-height: calc(100dvh - 6rem);
  padding: 0.75rem;
  background: #0b0d10;
}

.new-canvas-loading-skeleton > span,
.new-canvas-loading-skeleton__stage {
  min-width: 0;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 6px;
  background: linear-gradient(100deg, rgba(255, 255, 255, 0.035) 20%, rgba(255, 255, 255, 0.085) 45%, rgba(255, 255, 255, 0.035) 70%);
  background-size: 220% 100%;
  animation: new-canvas-skeleton-shimmer 1.25s linear infinite;
}

.new-canvas-loading-skeleton__stage {
  position: relative;
  overflow: hidden;
  background-color: #0c141d;
  background-image: linear-gradient(rgba(121, 146, 170, .11) 1px, transparent 1px), linear-gradient(90deg, rgba(121, 146, 170, .11) 1px, transparent 1px);
  background-size: 18px 18px;
  animation: none;
}

.new-canvas-loading-skeleton__ghost {
  position: absolute;
  display: block;
  width: 12%;
  min-width: 4rem;
  height: 4.7rem;
  border: 1px solid rgba(144, 181, 211, .26);
  border-radius: 5px;
  background: rgba(28, 42, 55, .68);
  box-shadow: inset 0 2rem 0 rgba(255, 255, 255, .025);
}

.new-canvas-loading-skeleton__ghost--one { left: 12%; top: 24%; }
.new-canvas-loading-skeleton__ghost--two { left: 34%; top: 45%; width: 15%; height: 5.8rem; }
.new-canvas-loading-skeleton__ghost--three { right: 22%; top: 20%; width: 14%; height: 5rem; }
.new-canvas-loading-skeleton__ghost--four { right: 10%; bottom: 17%; width: 17%; height: 6.4rem; }

.new-canvas-loading-skeleton__copy {
  position: absolute;
  top: 50%;
  left: 50%;
  display: grid;
  justify-items: center;
  gap: .4rem;
  min-width: 12rem;
  padding: 1rem 1.25rem;
  border: 1px solid rgba(171, 204, 224, .18);
  border-radius: 8px;
  background: rgba(8, 15, 22, .78);
  box-shadow: 0 .75rem 2rem rgba(0, 0, 0, .22);
  color: rgba(235, 243, 250, .9);
  transform: translate(-50%, -50%);
}

.new-canvas-loading-skeleton__copy strong { font-size: .88rem; font-weight: 700; }
.new-canvas-loading-skeleton__copy small { color: rgba(190, 207, 220, .62); font-size: .7rem; }

.new-canvas-loading-skeleton__spinner {
  width: 1.1rem;
  height: 1.1rem;
  border: 2px solid rgba(164, 201, 223, .25);
  border-top-color: #9cd3ee;
  border-radius: 50%;
  animation: new-canvas-loading-spin .8s linear infinite;
}

@keyframes new-canvas-loading-spin {
  to { transform: rotate(360deg); }
}

@keyframes new-canvas-skeleton-shimmer {
  from { background-position: 100% 0; }
  to { background-position: -120% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .new-canvas-loading-skeleton > span,
  .new-canvas-loading-skeleton__spinner {
    animation: none;
  }
}

@media (max-width: 720px) {
  .new-canvas-loading-skeleton {
    grid-template-columns: 3rem minmax(0, 1fr);
  }

  .new-canvas-loading-skeleton__panel {
    display: none;
  }
}

@media (min-width: 1680px) {
  .canvas-project-card-grid {
    grid-template-columns: repeat(6, minmax(0, 1fr));
