  border-color: rgba(94, 199, 255, 0.55);
  box-shadow: 0 0 0 3px rgba(94, 199, 255, 0.12);
}

.canvas-inspector textarea {
  height: 4.25rem;
  resize: none;
  padding: 0.65rem;
  line-height: 1.5;
}

.canvas-start {
  position: absolute;
  top: 39%;
  left: 50%;
  z-index: 1;
  display: grid;
  justify-items: center;
  gap: 2.15rem;
  width: min(64rem, calc(100% - 4rem));
  transform: translate(-50%, -50%);
}

.canvas-start-hint {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  margin: 0;
  color: rgba(255, 255, 255, 0.46);
  font-size: 0.88rem;
  font-weight: 700;
}

.canvas-start-hint strong {
  color: rgba(255, 255, 255, 0.8);
}

.canvas-quick-actions {
  display: grid;
  grid-template-columns: repeat(4, minmax(12.5rem, 16rem));
  gap: 0.85rem;
  justify-content: center;
  max-width: 100%;
}

.canvas-quick-action {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.72rem;
  min-width: 0;
  min-height: 4.08rem;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 0.55rem;
  padding: 0 1.05rem;
  background:
    linear-gradient(90deg, rgba(15, 18, 22, 0.92), rgba(17, 17, 17, 0.72)),
    #161616;
  color: #fff;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07);
  text-align: left;
}

.canvas-quick-action::after {
  position: absolute;
  inset: 0 0 0 auto;
  width: 42%;
  content: "";
  opacity: 0.82;
  background:
    linear-gradient(90deg, transparent, rgba(0, 0, 0, 0.3)),
    var(--canvas-action-art);
  background-size: cover;
  background-position: center;
}

.canvas-quick-action.story {
  --canvas-action-art: radial-gradient(circle at 82% 42%, #9aa8b7 0 0.8rem, transparent 0.85rem),
    radial-gradient(circle at 78% 58%, rgba(141, 151, 165, 0.72), transparent 3.4rem);
}

.canvas-quick-action.role {
  --canvas-action-art: radial-gradient(circle at 68% 38%, rgba(160, 88, 72, 0.86), transparent 3.5rem),
    linear-gradient(120deg, transparent, rgba(113, 21, 16, 0.86));
}

.canvas-quick-action.video {
  --canvas-action-art: linear-gradient(135deg, rgba(235, 235, 235, 0.4), rgba(12, 14, 16, 0.4)),
    linear-gradient(35deg, transparent 55%, #f05b39 56% 58%, transparent 59%);
}

.canvas-quick-action.audio {
  --canvas-action-art: radial-gradient(circle at 72% 44%, rgba(198, 205, 178, 0.5), transparent 3rem),
    linear-gradient(120deg, transparent, rgba(75, 91, 90, 0.82));
}

.canvas-quick-action span {
  position: relative;
  z-index: 1;
  display: grid;
  width: 1.45rem;
  height: 1.45rem;
  place-items: center;
  color: #fff;
}

.canvas-quick-action strong {
  position: relative;
  z-index: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.92rem;
  font-weight: 850;
}

.canvas-zoom-tools {
  position: absolute;
  left: 1rem;
  bottom: 0.8rem;
  /* Keep the viewport controls above the X6 node and edge surface. */
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 3.2rem;
  padding: 0 0.5rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 7px;
  background: rgba(24, 25, 24, 0.88);
  max-width: calc(100% - 2rem);
  overflow: visible;
  overscroll-behavior-inline: contain;
  scrollbar-width: none;
}

.canvas-zoom-tools::-webkit-scrollbar {
  display: none;
}

.canvas-zoom-tools button {
  position: relative;
  display: grid;
  width: 2.35rem;
  height: 2.35rem;
  place-items: center;
  flex: 0 0 2.35rem;
  border-radius: 7px;
  padding: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.6);
  line-height: 1;
}

.canvas-zoom-tools button[title]::after {
  position: absolute;
  bottom: calc(100% + 0.55rem);
  left: 50%;
  z-index: 30;
  max-width: min(18rem, calc(100vw - 2rem));
  padding: 0.42rem 0.62rem;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 6px;
  background: rgba(14, 18, 23, 0.96);
  box-shadow: 0 0.55rem 1.25rem rgba(0, 0, 0, 0.34);
  color: rgba(255, 255, 255, 0.92);
  content: attr(title);
  font-size: 0.72rem;
  font-weight: 650;
  line-height: 1.25;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 0.25rem);
  transition: opacity 140ms ease, transform 140ms ease;
  visibility: hidden;
  white-space: nowrap;
}

.canvas-zoom-tools button[title]:hover::after,
.canvas-zoom-tools button[title]:focus-visible::after {
  opacity: 1;
  transform: translate(-50%, 0);
  visibility: visible;
}

.canvas-zoom-tools button.active {
  background: rgba(255, 255, 255, 0.09);
  color: rgba(255, 255, 255, 0.92);
}

.canvas-zoom-tools button.canvas-view-tool.is-wide {
  display: inline-flex;
  width: auto;
  flex-basis: auto;
  align-items: center;
  gap: 0.45rem;
  padding: 0 0.7rem;
  white-space: nowrap;
}

.canvas-zoom-tools button.canvas-view-tool.is-wide span {
  font-size: 0.72rem;
  font-weight: 750;
}

.canvas-zoom-tools strong {
  display: grid;
  min-height: 1.85rem;
  place-items: center;
  color: rgba(255, 255, 255, 0.82);
  min-width: 2.6rem;
  text-align: center;
  font-size: 0.76rem;
  line-height: 1;
}

.canvas-zoom-menu-shell {
  position: relative;
  display: flex;
  flex: 0 0 auto;
}

.canvas-zoom-tools button.canvas-zoom-trigger {
  width: auto;
  min-width: 3.2rem;
  flex-basis: auto;
  padding: 0 0.5rem;
  font-size: 0.76rem;
  font-variant-numeric: tabular-nums;
  font-weight: 750;
}

.canvas-zoom-menu {
  position: absolute;
  right: 0;
  bottom: calc(100% + 0.55rem);
  z-index: 8;
  display: grid;
  gap: 0.15rem;
  width: 13.25rem;
  padding: 0.5rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(36, 37, 38, 0.98);
  box-shadow: 0 0.9rem 2.4rem rgba(0, 0, 0, 0.42);
}

.canvas-zoom-menu-value {
  display: flex;
  min-height: 2.45rem;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.25rem;
  padding: 0 0.7rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.95);
  font-variant-numeric: tabular-nums;
}

.canvas-zoom-menu-value input {
  display: block;
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.88rem;
  font-weight: 750;
  font-variant-numeric: tabular-nums;
  text-align: left;
  appearance: textfield;
}

.canvas-zoom-menu-value input::-webkit-inner-spin-button,
.canvas-zoom-menu-value input::-webkit-outer-spin-button {
  margin: 0;
  appearance: none;
}

.canvas-zoom-menu-value:focus-within {
  border-color: rgba(94, 199, 255, 0.72);
  box-shadow: 0 0 0 2px rgba(94, 199, 255, 0.14);
}

.canvas-zoom-menu-value span {
  color: rgba(255, 255, 255, 0.48);
  font-size: 0.82rem;
}

.canvas-zoom-tools .canvas-zoom-menu button,
.workbench-body .canvas-zoom-tools .canvas-zoom-menu button {
  display: flex;
  width: 100%;
  min-height: 2.25rem;
  height: auto;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex: 0 0 auto;
  padding: 0 0.7rem;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.82rem;
  text-align: left;
  white-space: nowrap;
}

.canvas-zoom-tools .canvas-zoom-menu button:hover,
.canvas-zoom-tools .canvas-zoom-menu button:focus-visible,
.workbench-body .canvas-zoom-tools .canvas-zoom-menu button:hover,
.workbench-body .canvas-zoom-tools .canvas-zoom-menu button:focus-visible {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.canvas-zoom-menu kbd {
  color: rgba(255, 255, 255, 0.48);
  font: inherit;
  font-size: 0.7rem;
}

.canvas-zoom-menu-separator {
  height: 1px;
  margin: 0.3rem 0;
  background: rgba(255, 255, 255, 0.1);
}

.canvas-zoom-tools button svg {
  margin: auto;
}

@media (max-width: 760px) {
  .canvas-zoom-tools button.canvas-view-tool.is-wide {
    width: 2.35rem;
    flex-basis: 2.35rem;
    padding: 0;
  }

  .canvas-zoom-tools button.canvas-view-tool.is-wide span {
    display: none;
  }
}

.new-canvas-root .canvas-template-section {
  display: none;
}

.canvas-sidebar svg,
.canvas-stage svg:not(.x6-graph-svg) {
  display: block;
  width: 1.18rem;
  height: 1.18rem;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.9;
}

.canvas-panel[data-canvas-sidebar-mode] {
  background: #101110;
}

.canvas-panel .canvas-sidebar {
  width: 13rem;
  background: rgba(21, 22, 22, 0.96);
}

.canvas-flow {
  z-index: 3;
  pointer-events: auto;
}

.canvas-stage svg.canvas-lib-edge-layer {
  position: absolute;
  left: -3200px;
  top: -2400px;
  display: block;
  z-index: 1;
  width: 6400px;
  height: 4800px;
  max-width: none;
  max-height: none;
  overflow: visible;
  pointer-events: auto;
  fill: none;
  stroke: none;
}

.canvas-stage.is-canvas-edges-hidden svg.canvas-lib-edge-layer {
  display: none;
}

.canvas-flow-edge-line,
.canvas-flow-edge-glow,
.canvas-flow-edge-preview {
  fill: none;
  pointer-events: none;
}

.canvas-flow-edge-hit {
  fill: none;
}

.canvas-flow-edge-hit {
  stroke: rgba(255, 255, 255, 0.001);
  stroke-width: 24;
  cursor: grab;
  pointer-events: all;
}

.canvas-flow-edge.is-disconnecting .canvas-flow-edge-line,
.canvas-flow-edge:hover .canvas-flow-edge-line {
  stroke: rgba(255, 255, 255, 0.98);
  stroke-width: 3;
}

.canvas-flow-edge.is-disconnecting .canvas-flow-edge-glow,
.canvas-flow-edge:hover .canvas-flow-edge-glow {
  stroke-width: 4.2;
  opacity: 1;
}

.canvas-flow-edge.is-disconnecting .canvas-flow-edge-line {
  opacity: 0.28;
  stroke-dasharray: 8 8;
}

.canvas-flow-edge.is-disconnecting .canvas-flow-edge-glow {
  opacity: 0.18;
}

.canvas-flow-edge-line {
  stroke: rgba(238, 242, 242, 0.92);
  stroke-linecap: round;
  stroke-width: 2.3;
}

.canvas-flow-edge-glow {
  stroke: #5ec7ff;
  stroke-dasharray: 72 148;
  stroke-dashoffset: 0;
  stroke-linecap: round;
  stroke-width: 3.6;
  opacity: 0.98;
  filter:
    drop-shadow(0 0 0.35rem rgba(94, 199, 255, 0.95))
    drop-shadow(0 0 0.9rem rgba(94, 199, 255, 0.5));
  animation: canvas-flow-edge-ribbon 1.45s linear infinite;
}

.canvas-flow-edge.active .canvas-flow-edge-line {
  stroke: rgba(232, 238, 238, 0.88);
}

.canvas-flow-edge-preview {
  stroke: #5ec7ff;
  stroke-linecap: round;
  stroke-width: 2.4;
  filter: drop-shadow(0 0 0.45rem rgba(94, 199, 255, 0.95));
}

.canvas-flow-edge-disconnect-preview {
  stroke: rgba(255, 255, 255, 0.98);
  stroke-dasharray: 10 7;
  stroke-width: 2.6;
  filter:
    drop-shadow(0 0 0.35rem rgba(94, 199, 255, 0.9))
    drop-shadow(0 0 0.75rem rgba(94, 199, 255, 0.45));
}

.canvas-x6-mount {
  opacity: 0;
  pointer-events: none;
}

.canvas-stage.is-x6-ready .canvas-x6-mount {
  opacity: 1;
  pointer-events: auto;
}

.canvas-distribution-gap-handle {
  position: absolute;
  z-index: 9;
  width: 18px;
  height: 18px;
  translate: -50% -50%;
  border: 1px solid rgba(98, 211, 236, 0.78);
  border-radius: 50%;
  background: #10282e;
  box-shadow: 0 0 0 3px rgba(70, 185, 206, 0.13);
  cursor: ew-resize;
}

.canvas-distribution-gap-handle.is-vertical {
  cursor: ns-resize;
}

.canvas-stage.is-x6-ready .canvas-flow {
  opacity: 1;
  pointer-events: none;
  visibility: hidden;
  will-change: auto;
}

.canvas-stage.is-x6-ready .canvas-flow-edge-glow {
  animation: none;
  filter: none;
}

.canvas-stage.is-x6-ready .canvas-flow .canvas-node-editor,
.canvas-stage.is-x6-ready .canvas-flow .canvas-node-action-toolbar {
  visibility: visible;
  pointer-events: auto;
}

.canvas-stage.is-x6-ready .canvas-flow .canvas-node-editor {
  transform: scale(var(--canvas-input-scale, 1));
  transform-origin: center top;
}

.canvas-stage.is-x6-ready > .canvas-node-editor,
.canvas-stage.is-x6-ready > .canvas-node-action-toolbar {
  visibility: visible;
  pointer-events: auto;
}

.canvas-x6-editor-overlay {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
}

.canvas-stage.is-x6-ready .canvas-x6-editor-overlay {
  transform: scale(var(--canvas-input-scale, 1));
  transform-origin: center top;
}

.canvas-x6-editor-overlay .canvas-node-editor {
  position: relative !important;
  box-sizing: border-box;
  width: 100%;
  min-height: 100%;
  height: 100%;
  transform: none !important;
}

.canvas-lib-node {
  position: absolute;
  z-index: 2;
  width: var(--node-width);
  min-height: var(--node-height);
  color: #f5f5f1;
  cursor: grab;
  pointer-events: auto;
  user-select: none;
  touch-action: none;
}

.canvas-node-action-toolbar {
  position: absolute;
  z-index: 6;
  display: flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.25rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  background: rgba(20, 22, 24, 0.94);
  box-shadow: 0 0.45rem 1.2rem rgba(0, 0, 0, 0.24);
  transform: scale(var(--canvas-toolbar-scale, 1));
  transform-origin: left bottom;
  pointer-events: auto;
  max-width: min(90vw, 30rem);
  overflow-x: auto;
  scrollbar-width: thin;
}

.canvas-node-action-zone {
  display: flex;
  align-items: center;
  gap: 0.15rem;
}

.canvas-node-action-zone + .canvas-node-action-zone {
  padding-left: 0.3rem;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
}

.canvas-node-action-toolbar button {
  display: grid;
  width: 1.8rem;
  height: 1.8rem;
  padding: 0;
  place-items: center;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: rgba(255, 255, 255, 0.7);
}

.canvas-node-action-toolbar button:hover {
  background: rgba(70, 185, 206, 0.16);
  color: #e8fcff;
}

.canvas-node-action-toolbar button.danger:hover {
  background: rgba(224, 77, 77, 0.16);
  color: #ffabab;
}

.canvas-node-action-toolbar svg {
  width: 1rem;
  height: 1rem;
}

.canvas-lib-node.is-dragging {
  cursor: grabbing;
  z-index: 5;
}

.canvas-lib-node.selected .canvas-generation-preview,
.canvas-lib-node.selected .canvas-text-card {
  border-color: rgba(255, 255, 255, 0.92);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.18),
    0 1.2rem 2.8rem rgba(0, 0, 0, 0.34);
}

.canvas-lib-node-title {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 2rem;
  margin-left: 0.1rem;
  color: #f7f7f4;
  font-size: 1.02rem;
  font-weight: 850;
}

.canvas-lib-node-title svg {
  width: 1.2rem;
  height: 1.2rem;
}

.canvas-animation-node-body {
  box-sizing: border-box;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  border: 1px solid rgba(232, 150, 255, 0.36);
  border-radius: 6px;
  background: #17191a;
}

.canvas-lib-node.canvas-animation-node .canvas-animation-node-body {
  height: 21.25rem;
  margin-top: 0.32rem;
}

.canvas-lib-node.canvas-animation-node.selected .canvas-animation-node-body {
  border-color: rgba(255, 255, 255, 0.92);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.16),
    0 1.2rem 2.8rem rgba(0, 0, 0, 0.34);
}

.canvas-animation-preview {
  position: relative;
  display: grid;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  place-items: center;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.025) 1px, transparent 1px),
    linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px),
    #111516;
  background-size: 18px 18px;
}

.canvas-animation-frame,
.canvas-animation-sheet {
  display: block;
  width: 100%;
  height: 100%;
}

.canvas-animation-frame {
  position: relative;
  overflow: hidden;
}

.canvas-animation-frame > img {
  position: absolute;
  display: block;
  max-width: none;
  object-fit: fill;
  animation-timing-function: steps(1, end);
  animation-iteration-count: infinite;
}

.canvas-animation-sheet {
  object-fit: contain;
}

.canvas-animation-preview-switch {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 2;
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 6px;
  background: rgba(13, 17, 18, 0.88);
}

.canvas-animation-preview-switch button {
  display: grid;
  width: 28px;
  height: 26px;
  padding: 0;
  place-items: center;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: rgba(255, 255, 255, 0.58);
  font-size: 11px;
}

.canvas-animation-preview-switch button.active {
  background: rgba(226, 121, 255, 0.2);
  color: #f7d5ff;
}

.canvas-animation-param-bar {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  background: #1b1e1f;
  color: #f2e9f5;
  font-size: 11px;
}

.canvas-animation-param-bar strong {
  color: #ec9cff;
  font-size: 12px;
}

.canvas-animation-param-bar small {
  min-width: 0;
  overflow: hidden;
  color: rgba(255, 255, 255, 0.46);
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.canvas-animation-empty {
  display: grid;
  max-width: 84%;
  justify-items: center;
  gap: 7px;
  color: rgba(255, 255, 255, 0.74);
  text-align: center;
}

.canvas-animation-empty strong {
  color: #f4eef5;
  font-size: 12px;
}

.canvas-animation-empty small {
  color: rgba(255, 255, 255, 0.44);
  font-size: 10px;
}

.canvas-image-node-body {
  position: relative;
  overflow: hidden;
}

.canvas-image-generation-mask {
  position: absolute;
  inset: 0;
  z-index: 3;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  max-width: none;
  border: 0;
  border-radius: 0;
  background: rgba(8, 17, 27, 0.92);
}

.canvas-animation-empty.is-failed strong,
.canvas-animation-empty.is-failed small {
  color: #ff9c9c;
}

.canvas-animation-empty-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid rgba(236, 156, 255, 0.38);
  border-radius: 50%;
  color: #ec9cff;
}

.canvas-animation-spinner {
  width: 30px;
  height: 30px;
  border: 2px solid rgba(255, 255, 255, 0.12);
  border-top-color: #ec9cff;
  border-radius: 50%;
  animation: canvas-animation-spin 800ms linear infinite;
}

.canvas-animation-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 6px;
}

.canvas-animation-action-picker {
  display: flex;
  flex: 1 1 auto;
  gap: 3px;
  min-width: 0;
}

.canvas-animation-action-picker button {
  min-width: 0;
  min-height: 30px;
  flex: 1 1 0;
  border: 1px solid var(--theme-control-border);
  border-radius: 4px;
  padding: 0 5px;
  background: var(--theme-control-background);
  color: color-mix(in srgb, var(--theme-control-active-text) 68%, transparent);
  font: inherit;
  font-size: 11px;
}

.canvas-animation-action-picker button:hover {
  border-color: var(--theme-control-hover-border);
  background: var(--theme-control-hover-background);
  color: var(--theme-control-active-text);
}

.canvas-animation-action-picker button.active {
  border-color: var(--theme-control-active-border);
  background: var(--theme-control-active-background);
  color: var(--theme-control-active-text);
}

.canvas-animation-frame-picker {
  display: inline-flex;
  flex: 0 0 auto;
