  display: grid;
  width: 4rem;
  height: 4rem;
  place-items: center;
  border-radius: 9999px;
  background: oklch(100% 0 0 / 0.12);
  color: oklch(92% 0.07 292);
  font-size: 1.8rem;
}

.generation-console {
  display: grid;
  grid-template-rows: auto auto auto auto minmax(8rem, auto) auto auto auto;
  gap: 0.9rem;
  padding: 1rem;
}

.calibration-panel {
  display: grid;
  gap: 0.85rem;
  padding: 0.9rem;
  border: 1px solid oklch(100% 0 0 / 0.08);
  border-radius: 8px;
  background: oklch(100% 0 0 / 0.03);
}

.calibration-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.55rem;
}

.console-tabs {
  display: flex;
  gap: 1rem;
  border-bottom: 1px solid oklch(100% 0 0 / 0.08);
}

.console-tab {
  padding: 0.45rem 0 0.65rem;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--text-muted);
}

.console-tab.active {
  color: oklch(88% 0.06 292);
  box-shadow: inset 0 -2px 0 oklch(88% 0.06 292);
}

.control-field {
  display: grid;
  gap: 0.45rem;
}

.control-field span {
  color: var(--text-muted);
  font-size: 0.82rem;
  font-weight: 600;
}

.control-field input,
.control-field select,
.control-field textarea,
.modal-search {
  width: 100%;
  border: 1px solid oklch(100% 0 0 / 0.08);
  border-radius: 8px;
  background: oklch(7% 0.012 260 / 0.78);
  color: var(--text-primary);
  font: inherit;
  outline: none;
}

.control-field input,
.control-field select,
.modal-search {
  min-height: 3rem;
  padding: 0 0.85rem;
}

.control-field textarea {
  min-height: 8rem;
  resize: vertical;
  padding: 0.85rem;
}

.model-list {
  display: grid;
  max-height: 14rem;
  overflow: auto;
  border: 1px solid oklch(100% 0 0 / 0.08);
  border-radius: 8px;
  padding: 0.45rem;
}

.model-option {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 0.75rem;
  padding: 0.7rem;
  border-radius: 8px;
}

.model-option.selected {
  background: oklch(100% 0 0 / 0.06);
}

.model-option span {
  display: grid;
  min-width: 0;
}

.model-option em,
.model-meta span {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 0.76rem;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.model-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.sync-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 3.5rem;
  border-radius: 8px;
  padding: 0 0.85rem;
  background: oklch(100% 0 0 / 0.05);
  color: var(--text-muted);
  font-size: 0.84rem;
}

.generate-now {
  min-height: 3.2rem;
  background: oklch(64% 0.2 292);
  color: white;
}

.export-panel {
  display: grid;
  gap: 0.9rem;
  border-radius: 8px;
  padding: 1rem;
}

.export-panel-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.export-summary span {
  border-radius: 9999px;
  padding: 0.35rem 0.65rem;
  background: oklch(100% 0 0 / 0.06);
  color: var(--text-muted);
  font-size: 0.78rem;
}

.export-detail {
  display: grid;
  gap: 0.75rem;
}

.export-history {
  display: grid;
  gap: 0.6rem;
  padding: 0.85rem;
  border: 1px solid oklch(100% 0 0 / 0.08);
  border-radius: 8px;
  background: oklch(100% 0 0 / 0.03);
}

.export-history-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.export-history-list {
  display: grid;
  gap: 0.55rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.export-history-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.65rem 0.75rem;
  border-radius: 8px;
  background: oklch(100% 0 0 / 0.04);
}

.export-history-item div {
  display: grid;
  gap: 0.2rem;
}

.export-history-item span,
.export-history-item small {
  color: var(--text-muted);
  font-size: 0.78rem;
}

.export-history-empty {
  margin: 0;
  color: var(--text-muted);
}

.download-placeholder {
  margin: 0;
  color: var(--text-muted);
}

.export-warning {
  border-radius: 8px;
  padding: 0.85rem;
  background: oklch(100% 0 0 / 0.05);
}

.export-delivery-card,
.generation-diagnostics {
  display: grid;
  gap: 0.65rem;
  padding: 0.85rem;
  border-radius: 8px;
  border: 1px solid oklch(100% 0 0 / 0.08);
  background: oklch(100% 0 0 / 0.03);
}

.export-delivery-card header,
.generation-diagnostics-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.export-delivery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 0.5rem 0.75rem;
  margin: 0;
}

.export-delivery-grid div {
  display: grid;
  gap: 0.15rem;
}

.export-delivery-grid dt,
.export-delivery-grid dd {
  margin: 0;
}

.export-delivery-grid dt,
.generation-diagnostics-meta,
.export-download-muted {
  color: var(--text-muted);
  font-size: 0.78rem;
}

.export-download-link {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 0.15em;
}

.generation-diagnostics-grid {
  display: grid;
  gap: 0.75rem;
}

.generation-diagnostics-card {
  display: grid;
  gap: 0.55rem;
  padding: 0.8rem;
  border-radius: 8px;
  background: oklch(100% 0 0 / 0.04);
}

.generation-diagnostics-card header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.5rem;
}

.generation-diagnostics-list {
  display: grid;
  gap: 0.45rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.generation-diagnostics-list li {
  display: grid;
  gap: 0.15rem;
  padding: 0.5rem 0.65rem;
  border-radius: 8px;
  background: oklch(100% 0 0 / 0.04);
}

.export-warning ul {
  margin: 0.5rem 0 0;
  padding-left: 1.1rem;
}

.workbench-toast {
  min-height: 1.5rem;
  margin: 0;
  padding: 0 0.35rem;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background: oklch(0% 0 0 / 0.72);
  cursor: default;
}

.script-modal {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  width: min(88rem, 100%);
  max-height: min(58rem, calc(100vh - 3.5rem));
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1.6rem;
  padding: 1.8rem 1.85rem 1.6rem;
  background: linear-gradient(180deg, rgba(31, 31, 37, 0.98), rgba(26, 26, 31, 0.98));
  box-shadow: 0 2rem 6rem oklch(0% 0 0 / 0.45);
}

.upload-studio-modal {
  width: min(68rem, calc(100vw - 14rem));
  max-height: min(52rem, calc(100vh - 6rem));
  padding: 1.45rem;
}

.original-script-modal {
  display: grid;
  gap: 1rem;
  width: min(52rem, 100%);
  max-height: min(42rem, calc(100vh - 3rem));
  overflow: auto;
  border: 1px solid oklch(100% 0 0 / 0.1);
  border-radius: 8px;
  padding: 1.25rem;
  background: oklch(15% 0.018 285 / 0.98);
  box-shadow: 0 2rem 6rem oklch(0% 0 0 / 0.45);
}

.original-script-head {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}

.original-script-head p {
  margin: 0.25rem 0 0;
}

.original-script-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
}

.original-script-inspiration {
  grid-column: 1 / -1;
}

.original-script-inspiration textarea {
  min-height: 8rem;
}

.original-script-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 0.75rem;
  align-items: center;
}

.original-script-actions p {
  display: flex;
  gap: 0.75rem;
  margin: 0;
  color: var(--text-muted);
}

.modal-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr)) auto;
  gap: 0.5rem;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1.1rem;
  padding: 0.55rem;
  background: rgba(17, 18, 23, 0.4);
}

.modal-tab,
.modal-close {
  border-radius: 1rem;
  background: transparent;
  color: var(--text-muted);
}

.modal-tab {
  min-height: 4.6rem;
  font-size: 1.1rem;
  font-weight: 800;
}

.modal-tab.active {
  background: rgba(83, 72, 110, 0.88);
  color: #fff;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.modal-close {
  width: 2.5rem;
  padding: 0;
  justify-self: end;
  color: rgba(255, 255, 255, 0.92);
  font-size: 2.2rem;
}

.upload-modal-close {
  grid-column: 4;
  width: 3.4rem;
  height: 3.4rem;
}

.modal-panel {
  min-height: 34rem;
  overflow: auto;
  padding: 1.2rem 0 0;
}

.upload-panel-stack,
.upload-library-panel {
  display: grid;
  align-content: start;
  gap: 1rem;
}

.library-placeholder,
.upload-dropzone {
  display: grid;
  border-radius: 1.35rem;
  background: rgba(43, 45, 55, 0.92);
  color: var(--text-muted);
}

.upload-library-panel {
  gap: 1.2rem;
}

.upload-studio-modal .upload-library-panel {
  min-height: 0;
  padding-bottom: 1rem;
}

.script-manual-field {
  position: relative;
  display: grid;
  min-height: 34rem;
}

.script-manual-field textarea {
  width: 100%;
  min-height: 34rem;
  resize: vertical;
  padding: 1.45rem 1.55rem 2.3rem;
  border: 2px solid rgba(255, 255, 255, 0.92);
  border-radius: 1.35rem;
  outline: none;
  background: rgba(26, 27, 36, 0.96);
  color: rgba(245, 246, 252, 0.94);
  font: inherit;
  font-size: 1rem;
  line-height: 1.7;
}

.upload-studio-modal .script-manual-field,
.upload-studio-modal .script-manual-field textarea {
  min-height: clamp(19rem, calc(100dvh - 32rem), 28rem);
}

.script-manual-field textarea::placeholder {
  color: rgba(220, 222, 232, 0.44);
}

.script-manual-field textarea:focus {
  border-color: rgba(255, 255, 255, 0.98);
  box-shadow: 0 0 0 3px rgba(143, 99, 255, 0.18);
}

.script-manual-count {
  position: absolute;
  right: 1.35rem;
  bottom: 1.05rem;
  color: rgba(220, 222, 232, 0.62);
  font-size: 0.9rem;
  font-weight: 800;
  pointer-events: none;
}

.script-manual-look-controls {
  position: relative;
  z-index: 4;
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  min-height: 4.2rem;
}

.script-manual-look-control-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(12rem, 1fr));
  gap: 0.75rem;
  width: min(34rem, 100%);
}

.script-conversion-skill-control {
  width: 100%;
}

.script-manual-look-control-row .single-episode-text-model-dropdown {
  width: 100%;
}

.script-conversion-skill-control .single-episode-look-trigger {
  grid-template-columns: minmax(0, 1fr) auto auto;
  min-height: 2.5rem;
  padding-right: 0.55rem;
  padding-left: 0.8rem;
}

.script-conversion-skill-control .single-episode-look-trigger > small {
  color: rgba(197, 183, 255, 0.9);
  font-size: 0.75rem;
  font-weight: 800;
  white-space: nowrap;
}

.selection-picker-layer {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  isolation: isolate;
}

.selection-picker-scrim {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  border: 0;
  border-radius: 0;
  background: rgba(2, 3, 8, 0.78);
  backdrop-filter: blur(5px);
}

.selection-picker-modal {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-rows: auto auto minmax(18rem, 1fr) auto;
  width: min(58rem, calc(100vw - 3rem));
  height: min(46rem, calc(100dvh - 3rem));
  max-height: min(46rem, calc(100dvh - 3rem));
  overflow: hidden;
  border: 1px solid var(--theme-control-border, rgba(255, 255, 255, 0.12));
  border-radius: 8px;
  background: var(--theme-panel-background, #171820);
  box-shadow: 0 2.2rem 6rem rgba(0, 0, 0, 0.58);
  animation: selection-picker-enter 160ms ease-out both;
}

.selection-picker-modal.has-source-tabs {
  grid-template-rows: auto auto auto minmax(18rem, 1fr) auto;
}

@keyframes selection-picker-enter {
  from { opacity: 0; transform: translateY(0.5rem) scale(0.99); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.selection-picker-header,
.selection-picker-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.15rem;
}

.selection-picker-header {
  border-bottom: 1px solid var(--theme-control-border, rgba(255, 255, 255, 0.1));
}

.selection-picker-header > div {
  display: grid;
  gap: 0.15rem;
}

.selection-picker-header span {
  color: var(--theme-accent, #b694ff);
  font-size: 0.68rem;
  font-weight: 900;
}

.selection-picker-header h2 {
  margin: 0;
  color: var(--theme-text, rgba(255, 255, 255, 0.94));
  font-size: 1.05rem;
  letter-spacing: 0;
}

.selection-picker-close {
  width: 2.5rem;
  height: 2.5rem;
  padding: 0;
  border: 1px solid var(--theme-control-border, rgba(255, 255, 255, 0.1));
  border-radius: 8px;
  background: var(--theme-surface-background, rgba(255, 255, 255, 0.05));
  color: var(--theme-text, #fff);
  font-size: 1.6rem;
  line-height: 1;
}

.selection-picker-tabs {
  display: flex;
  gap: 0.25rem;
  padding: 0.75rem 1.15rem 0;
}

.selection-picker-source-tabs {
  display: flex;
  gap: 0.35rem;
  padding: 0.75rem 1.15rem 0;
}

.selection-picker-source-tabs button {
  min-height: 2.35rem;
  padding: 0 1rem;
  border: 1px solid var(--theme-control-border, rgba(255, 255, 255, 0.1));
  border-radius: 8px;
  background: var(--theme-surface-background, rgba(255, 255, 255, 0.04));
  color: var(--text-muted, rgba(255, 255, 255, 0.62));
  font-weight: 800;
}

.selection-picker-source-tabs button.active {
  border-color: var(--theme-accent, rgba(157, 121, 255, 0.86));
  background: var(--theme-accent-soft, rgba(128, 92, 255, 0.2));
  color: var(--theme-text, #fff);
}

.selection-picker-tabs button {
  display: inline-flex;
  min-height: 2.5rem;
  align-items: center;
  gap: 0.55rem;
  padding: 0 0.9rem;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--text-muted, rgba(255, 255, 255, 0.6));
  font-weight: 800;
}

.selection-picker-tabs button.active {
  border-color: var(--theme-control-border, rgba(255, 255, 255, 0.12));
  background: var(--theme-accent-soft, rgba(128, 92, 255, 0.2));
  color: var(--theme-text, #fff);
}

.selection-picker-tabs small {
  min-width: 1.3rem;
  padding: 0.15rem 0.35rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  font-size: 0.68rem;
  text-align: center;
}

.selection-picker-content {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-content: start;
  gap: 0.65rem;
  margin: 0.75rem 1.15rem 1rem;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

.selection-picker-item {
  display: grid;
  grid-template-columns: 2.6rem minmax(0, 1fr) auto 1.25rem;
  min-height: 4.5rem;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem;
  border: 1px solid var(--theme-control-border, rgba(255, 255, 255, 0.08));
  border-radius: 8px;
  background: var(--theme-surface-background, rgba(255, 255, 255, 0.04));
  color: var(--theme-text, rgba(255, 255, 255, 0.9));
  text-align: left;
}

.selection-picker-item:hover,
.selection-picker-item.active {
  border-color: var(--theme-accent, rgba(157, 121, 255, 0.86));
  background: var(--theme-accent-soft, rgba(128, 92, 255, 0.16));
}

.selection-picker-item > img,
.selection-picker-item-gallery,
.selection-picker-item-icon {
  width: 2.6rem;
  height: 2.6rem;
  border-radius: 8px;
  object-fit: cover;
}

.selection-picker-item-gallery {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-template-rows: repeat(2, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  background: var(--panel-border, rgba(255, 255, 255, 0.12));
}

.selection-picker-item-gallery img {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  object-fit: cover;
}

.selection-picker-item-icon {
  display: grid;
  place-items: center;
  background: var(--theme-accent-soft, rgba(128, 92, 255, 0.18));
  color: var(--theme-accent, #c79dff);
}

.selection-picker-item-copy {
  display: grid;
  min-width: 0;
  gap: 0.2rem;
}

.selection-picker-item-copy strong,
.selection-picker-item-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.selection-picker-item-copy small {
  color: var(--text-muted, rgba(255, 255, 255, 0.54));
  font-size: 0.72rem;
}

.selection-picker-item em {
  color: var(--theme-accent, #c7a8ff);
  font-size: 0.75rem;
  font-style: normal;
  font-weight: 800;
  white-space: nowrap;
}

.selection-picker-item-check {
  opacity: 0;
  color: var(--theme-accent, #c7a8ff);
  font-weight: 900;
}

.selection-picker-item.active .selection-picker-item-check {
  opacity: 1;
}

.selection-picker-empty {
  grid-column: 1 / -1;
  display: grid;
  min-height: 18rem;
  place-items: center;
  align-content: center;
  gap: 0.75rem;
  border: 1px solid var(--theme-control-border, rgba(255, 255, 255, 0.08));
  border-radius: 8px;
  color: var(--text-muted, rgba(255, 255, 255, 0.62));
}

.selection-picker-empty span {
  display: grid;
  width: 3rem;
  height: 3rem;
  place-items: center;
  border-radius: 8px;
  background: var(--theme-accent-soft, rgba(128, 92, 255, 0.14));
  color: var(--theme-accent, #c79dff);
}

.selection-picker-footer {
  justify-content: flex-end;
  border-top: 1px solid var(--theme-control-border, rgba(255, 255, 255, 0.1));
}

.selection-picker-cancel,
.selection-picker-confirm {
  min-width: 6rem;
  min-height: 2.6rem;
  border-radius: 8px;
  font-weight: 800;
}

.selection-picker-cancel {
  border: 1px solid var(--theme-control-border, rgba(255, 255, 255, 0.1));
  background: transparent;
  color: var(--theme-text, rgba(255, 255, 255, 0.82));
}

.selection-picker-confirm {
  border: 0;
  background: var(--theme-primary-action, linear-gradient(90deg, #7957ff, #16b7ed));
  color: #fff;
}

.selection-picker-confirm:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

@media (max-width: 720px) {
  .selection-picker-layer {
    padding: 0.75rem;
  }

  .selection-picker-modal {
    width: 100%;
    max-height: calc(100dvh - 1.5rem);
  }

  .selection-picker-content {
    grid-template-columns: 1fr;
  }

  .selection-picker-tabs {
    overflow-x: auto;
  }

  .selection-picker-source-tabs {
    overflow-x: auto;
  }
}

.script-manual-look-controls .single-episode-look-select {
  min-width: 0;
}

.script-manual-look-controls .single-episode-look-dropdown {
  bottom: calc(100% + 0.6rem);
  top: auto;
}

.library-placeholder {
  gap: 0.6rem;
  min-height: 18rem;
  place-items: center;
  padding: 1.8rem;
  text-align: center;
}

.upload-tip-line {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin: 0;
  color: rgba(235, 237, 244, 0.86);
  font-size: 0.98rem;
  font-weight: 700;
}

.upload-tip-icon {
  color: rgba(255, 255, 255, 0.68);
  font-size: 1.15rem;
}

.upload-tip-link {
  padding: 0;
  border: 0;
