.episode-canvas-copy strong {
  font-size: 1.02rem;
}

.episode-canvas-copy span {
  color: var(--interior-muted);
  font-size: 0.86rem;
}

.episode-inline-link {
  padding: 0;
  border: 0;
  background: transparent;
  color: #f6f1ff;
  font: inherit;
  font-weight: 800;
  text-decoration: underline;
  text-underline-offset: 0.18rem;
}

.interior-toast {
  padding: 0.65rem 1.85rem 1rem;
  opacity: 0.72;
}

.global-workbench-toast-stack {
  position: fixed;
  top: 1.15rem;
  right: auto;
  bottom: auto;
  left: 50%;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  width: min(22rem, calc(100vw - 2rem));
  max-height: calc(100vh - 2.3rem);
  margin: 0;
  overflow-y: auto;
  pointer-events: none;
  scrollbar-width: none;
  transform: translateX(-50%);
}

.global-workbench-toast-stack::-webkit-scrollbar {
  display: none;
}

.global-workbench-toast-stack.interior-toast {
  padding: 0;
  opacity: 1;
}

.global-workbench-toast {
  position: relative;
  inset: auto;
  z-index: auto;
  display: grid;
  flex: 0 0 auto;
  gap: 0.18rem;
  width: 100%;
  min-height: 0;
  margin: 0;
  padding: 0.78rem 0.92rem;
  border: 1px solid transparent;
  border-radius: 8px;
  box-shadow: 0 18px 45px oklch(0% 0 0 / 0.24);
  color: #f8fff9;
  pointer-events: none;
  transform: none;
  animation: workbenchToastEnter 180ms ease-out both;
}

.global-workbench-toast strong {
  color: inherit;
  font-size: 0.84rem;
  line-height: 1.2;
  letter-spacing: 0;
}

.global-workbench-toast span {
  color: oklch(98% 0.015 150 / 0.9);
  font-size: 0.78rem;
  line-height: 1.45;
}

.global-workbench-toast.success {
  border-color: oklch(72% 0.17 150 / 0.72);
  background: linear-gradient(135deg, oklch(37% 0.12 150 / 0.98), oklch(26% 0.08 165 / 0.98));
}

.global-workbench-toast.error {
  border-color: oklch(68% 0.2 28 / 0.78);
  background: linear-gradient(135deg, oklch(42% 0.16 28 / 0.98), oklch(27% 0.11 20 / 0.98));
}

.global-workbench-toast.error span {
  color: oklch(98% 0.018 28 / 0.9);
}

.global-workbench-toast.warning {
  border-color: oklch(79% 0.16 82 / 0.82);
  background: linear-gradient(135deg, oklch(49% 0.13 76 / 0.98), oklch(32% 0.09 66 / 0.98));
}

.global-workbench-toast.warning span {
  color: oklch(98% 0.025 86 / 0.94);
}

.global-workbench-toast.is-persistent {
  opacity: 1;
  animation: none;
  transform: none;
}

.global-workbench-toast.interior-toast {
  padding: 0.78rem 0.92rem;
  opacity: 1;
}

.global-workbench-toast-stack.community-window-toast {
  top: 5.25rem;
  z-index: 120;
}

.global-workbench-toast-stack.account-settings-toast {
  z-index: 120;
}

.global-workbench-toast-stack.asset-generator-toast {
  z-index: 120;
}

@keyframes workbenchToastEnter {
  from {
    opacity: 0;
    transform: translateY(-0.4rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.episode-hub-shell {
  min-height: calc(100vh - 78px);
  border: 1px solid var(--interior-line);
  border-top: 0;
  border-left: 0;
  border-radius: 0 0.45rem 0.45rem 0;
  background: #08090e;
  padding: 1.8rem 1.6rem 2rem;
}

.episode-hub-shell.empty .episode-hub-cards {
  display: grid;
  gap: 1rem;
  width: min(100%, 56rem);
  margin: 8.5rem auto 0;
}

.episode-hub-shell.populated .episode-hub-grid {
  --episode-hub-card-height: 15rem;
  --episode-hub-launch-gap: 0.55rem;
  --library-media-card-width: 15rem;
  display: grid;
  grid-template-columns: repeat(2, minmax(var(--library-media-card-width), var(--library-media-card-width)));
  gap: 1rem;
  align-items: start;
  width: fit-content;
  max-width: 100%;
}

.episode-hub-shell.populated .episode-hub-launches {
  display: grid;
  gap: var(--episode-hub-launch-gap);
}

.episode-hub-shell.populated .episode-hub-list {
  display: contents;
}

.episode-hub-tabs,
.episode-launch-card,
.episode-launch-copy,
.single-episode-modal-head,
.single-episode-actions {
  display: flex;
}

.episode-hub-tabs {
  align-items: center;
  gap: 1.35rem;
}

.episode-hub-tabs strong,
.episode-history-tab {
  color: #fff;
  font-size: 1.55rem;
  font-weight: 900;
}

.episode-history-tab {
  padding: 0;
  border: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.7);
}

.episode-hub-launches {
  display: grid;
  gap: 1.15rem;
}

.episode-hub-list {
  display: grid;
  grid-template-columns: minmax(17.25rem, 17.25rem);
  gap: 1rem;
  align-content: start;
  min-height: 100%;
}

.episode-launch-card {
  position: relative;
  align-items: stretch;
  min-height: 14.75rem;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 2rem;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.01));
}

.episode-launch-card.single {
  min-height: 10.25rem;
}

.episode-hub-shell.populated .episode-launch-card {
  min-height: calc((var(--episode-hub-card-height) - var(--episode-hub-launch-gap)) / 2);
  border-radius: 1.15rem;
}

.episode-hub-shell.populated .episode-launch-card.single {
  min-height: calc((var(--episode-hub-card-height) - var(--episode-hub-launch-gap)) / 2);
}

.episode-library-card {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.8rem;
  min-height: 6.25rem;
  padding: 0.95rem 1rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1.4rem;
  cursor: pointer;
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
  background:
    radial-gradient(circle at 72% 18%, rgba(130, 100, 255, 0.18), transparent 10rem),
    linear-gradient(135deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.02));
}

.episode-hub-shell.populated .episode-library-card {
  min-height: var(--episode-hub-card-height);
  padding: 0.82rem 0.9rem 0.9rem;
  border-radius: 1.15rem;
}

.episode-library-card:hover {
  border-color: rgba(255, 255, 255, 0.16);
  box-shadow: 0 1.2rem 2.5rem rgba(0, 0, 0, 0.24);
  transform: translateY(-2px);
}

.episode-workbench-screen {
  display: grid;
  gap: 1rem;
}

.episode-workbench-utility-bar {
  grid-column: 2 / -1;
  grid-row: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 3.45rem;
  padding: 0.32rem 0.4rem 0.5rem;
}

.episode-workbench-utility-search {
  flex: 1 1 auto;
  min-height: 2.85rem;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 0.92rem;
  background: linear-gradient(180deg, rgba(18, 19, 27, 0.98), rgba(20, 21, 29, 0.98));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.episode-workbench-utility-actions {
  display: flex;
