}

.episode-workbench-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0 1rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.82rem;
  background: rgba(24, 25, 34, 0.96);
  color: rgba(246, 246, 252, 0.92);
  font-size: 0.88rem;
  font-weight: 800;
  white-space: nowrap;
}

.episode-workbench-pill.promo {
  border-color: rgba(86, 226, 241, 0.24);
  background: linear-gradient(90deg, #d9c755, #17d4f2);
  color: #111319;
}

.episode-workbench-pill.icon {
  min-width: 2.75rem;
  padding-inline: 0.75rem;
}

.episode-workbench-pill.avatar {
  min-width: 2.85rem;
  border-radius: 0.95rem;
  background: linear-gradient(180deg, #6d7cff, #6170ff);
  color: #fff;
}

.episode-media-chrome {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 2.8rem;
}

.episode-workbench-back-button {
  position: fixed;
  top: 0.15rem;
  left: 0.15rem;
  z-index: 40;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 4.9rem;
  height: 2.35rem;
  padding: 0 1rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 1.15rem;
  background:
    linear-gradient(180deg, rgba(24, 26, 34, 0.96), rgba(11, 13, 19, 0.98));
  color: rgba(244, 244, 251, 0.94);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    0 0.85rem 2rem rgba(0, 0, 0, 0.28),
    0 0 0 1px rgba(255, 255, 255, 0.02);
  font-size: 0.98rem;
  font-weight: 800;
  letter-spacing: 0;
  line-height: 1;
  white-space: nowrap;
  backdrop-filter: blur(12px);
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease,
    transform 160ms ease;
}

.episode-workbench-back-button:hover,
.episode-workbench-back-button:focus-visible {
  border-color: rgba(255, 255, 255, 0.2);
  background:
    linear-gradient(180deg, rgba(36, 39, 49, 0.98), rgba(18, 20, 28, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    0 1rem 2.4rem rgba(0, 0, 0, 0.34),
    0 0 0 1px rgba(255, 255, 255, 0.04);
  transform: translateX(-1px);
}

.cinematic-layout {
  grid-template-columns: minmax(7rem, 7rem) minmax(0, 1fr) minmax(25rem, 27rem);
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: 0.6rem;
  min-height: 52rem;
  align-items: stretch;
}

.episode-media-header {
  grid-column: 2 / -1;
  grid-row: 2;
  border-radius: 1rem;
  padding: 0.2rem 1.1rem 0.1rem;
  background: linear-gradient(180deg, rgba(26, 27, 36, 0.98), rgba(24, 25, 34, 0.95));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.episode-media-tabs {
  display: flex;
  justify-content: center;
  flex: 1 1 auto;
  gap: clamp(2rem, 6vw, 4.25rem);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 0.05rem;
}

.episode-media-tab {
  position: relative;
  padding: 0 0 0.7rem;
  border: 0;
  background: transparent;
  color: rgba(205, 205, 220, 0.82);
  font-size: 0.96rem;
  font-weight: 700;
}

.episode-media-tab.active {
  color: #f5d8ff;
}

.episode-media-tab.active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 3px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(244, 211, 255, 0.9), rgba(255, 255, 255, 0.75));
}

.cinematic-sidebar,
.cinematic-stage,
.director-console {
  background: linear-gradient(180deg, rgba(28, 29, 39, 0.98), rgba(25, 26, 35, 0.96));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.cinematic-sidebar {
  grid-column: 1;
  grid-row: 2 / 4;
  position: relative;
  z-index: 3;
  overflow: visible;
  padding: 0.8rem 0.95rem 0.9rem;
  border-radius: 1rem;
}

.cinematic-thumb {
  position: relative;
  min-height: 5.15rem;
  height: 5.15rem;
  display: block;
  overflow: hidden;
  padding: 0.14rem;
  border-radius: 0.5rem;
  background: #000;
}

.shot-thumb-shell {
  position: relative;
  width: 100%;
  min-width: 0;
  z-index: 0;
}

.shot-thumb-shell:hover,
.shot-thumb-shell:focus-within {
  z-index: 60;
}

.shot-thumb-shell > .shot-thumb {
  width: 100%;
}

.shot-thumb-menu-button {
  position: absolute;
  right: 0;
  bottom: 0;
  z-index: 6;
  width: auto;
  height: auto;
  min-width: 0;
  min-height: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: rgba(245, 245, 250, 0.92);
  overflow: visible;
  opacity: 0;
  transform: translateY(0.18rem) scale(0.96);
  transition:
    opacity 160ms ease,
    transform 160ms ease,
    color 160ms ease;
}

.shot-thumb-shell:hover .shot-thumb-menu-button,
.shot-thumb-shell:focus-within .shot-thumb-menu-button {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.shot-thumb-menu-button:hover,
.shot-thumb-menu-button:focus-visible {
  background: transparent;
  color: #fff;
}

.shot-thumb-menu-button span {
  position: static;
  display: block;
  font-size: 1.2rem;
  font-weight: 800;
  line-height: 1;
  transform: translate(0.08rem, 0.08rem);
  pointer-events: none;
}

.cinematic-thumb.has-image-preview,
.cinematic-thumb.has-video-preview {
  min-height: 5.35rem;
  height: 5.35rem;
  padding: 0.14rem;
}

.shot-thumb.has-image-preview > span,
.shot-thumb.has-video-preview > span {
  left: 0.62rem;
  top: 0.42rem;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.7);
}

.shot-thumb.has-image-preview > strong,
.shot-thumb.has-video-preview > strong {
  right: 0.5rem;
  top: 0.42rem;
  background: rgba(92, 92, 102, 0.92);
}

.shot-sidebar-head,
.shot-add-card,
.timeline-button,
.secondary-action.compact {
  font-size: 0.88rem;
}

.shot-thumb span {
  font-size: 0.95rem;
  z-index: 2;
}

.shot-thumb strong {
  font-size: 0.7rem;
  line-height: 1;
  white-space: nowrap;
  z-index: 2;
}

.cinematic-thumb > span {
  position: absolute;
  left: 0.45rem;
  top: 0.42rem;
}

.cinematic-thumb > strong {
  position: absolute;
  right: 0.45rem;
  top: 0.34rem;
}

.shot-thumb em {
  display: none;
}

.shot-thumb-preview {
  position: absolute;
  inset: 0.14rem;
  z-index: 1;
  pointer-events: none;
  overflow: hidden;
  min-height: 0;
  height: auto;
  border-radius: 0.36rem;
  background: #000;
}

.shot-thumb-placeholder {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  background:
    radial-gradient(circle at 50% 42%, rgba(147, 139, 209, 0.32) 0 0.55rem, transparent 0.58rem),
    radial-gradient(circle at 50% 48%, rgba(127, 111, 211, 0.18), transparent 36%),
    linear-gradient(180deg, rgba(16, 17, 22, 0.96), rgba(7, 8, 12, 1));
}

.shot-thumb-placeholder span {
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 0.25rem;
  background:
    radial-gradient(circle at 67% 35%, rgba(203, 197, 255, 0.8) 0 0.22rem, transparent 0.24rem),
    linear-gradient(135deg, transparent 0 45%, rgba(179, 168, 245, 0.65) 46% 70%, transparent 71%),
    linear-gradient(180deg, rgba(77, 75, 105, 0.95), rgba(40, 41, 57, 0.98));
}

.shot-thumb-preview video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.shot-thumb-preview i {
  position: absolute;
  right: 0.28rem;
  top: 0.28rem;
  display: grid;
  width: 1rem;
  height: 1rem;
  place-items: center;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.92);
  color: #111318;
  font-size: 0.5rem;
  font-style: normal;
}

.cinematic-thumb .shot-thumb-preview {
  width: auto;
  min-height: 0;
  height: auto;
  border-radius: 0.36rem;
  background:
    radial-gradient(circle at 70% 24%, rgba(149, 122, 255, 0.2), transparent 1.2rem),
    #000;
}

.cinematic-thumb.active {
  border-color: rgba(160, 92, 255, 0.92);
  box-shadow: 0 0 0 2px rgba(163, 95, 255, 0.2);
}

.shot-add-card {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto auto;
  place-items: center;
  gap: 0.25rem;
  min-height: 5.9rem;
  padding: 0.7rem 0.55rem 0.6rem;
  border: 0;
  border-radius: 0.5rem;
  background: #3b3d49;
  color: rgba(245, 246, 252, 0.9);
  text-align: center;
}

.shot-add-card span {
  grid-column: 1;
  grid-row: 1;
  display: grid;
  place-items: center;
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  font-size: 1.25rem;
  font-weight: 300;
  line-height: 1;
}

.shot-add-card strong {
  grid-column: 1;
  grid-row: 2;
  justify-self: center;
  background: transparent;
  padding: 0;
  color: inherit;
  font-size: 0.82rem;
  font-weight: 700;
}

.shot-thumb-preview img,
.shot-thumb-preview video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  pointer-events: none;
}

.shot-thumb.has-image-preview .shot-thumb-preview,
.shot-thumb.has-video-preview .shot-thumb-preview {
  background: #111219;
  border-radius: 0.28rem;
}

.shot-thumb.has-image-preview .shot-thumb-preview img,
.shot-thumb.has-video-preview .shot-thumb-preview img,
.shot-thumb.has-video-preview .shot-thumb-preview video {
  object-fit: cover;
  object-position: center top;
  padding: 0;
}

.cinematic-stage {
  grid-column: 2;
  grid-row: 3;
  display: grid;
  min-width: 0;
  position: relative;
  z-index: 1;
  grid-template-rows: auto minmax(0, 1fr);
  min-height: 0;
  height: auto;
  padding: 1rem 1.15rem;
  border-radius: 1rem;
  overflow: hidden;
}

.cinematic-stage-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.85rem;
  color: rgba(216, 216, 232, 0.86);
  min-height: 1.6rem;
  font-size: 0.86rem;
}

.cinematic-stage-copy {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
}

.cinematic-stage-copy span {
  color: rgba(171, 173, 190, 0.74);
  font-size: 0.76rem;
}

.cinematic-stage-actions {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.stage-head-upload-button {
  min-height: 2rem;
  padding: 0 0.8rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  color: rgba(241, 242, 249, 0.92);
  font-size: 0.82rem;
  font-weight: 800;
}

.cinematic-stage-empty {
  min-height: 30rem;
  height: 100%;
  color: rgba(193, 194, 209, 0.78);
}

.cinematic-folder {
