}

.stage-inline-link-button {
  padding: 0;
  cursor: pointer;
}

.stage-image-library {
  display: grid;
  align-content: start;
  gap: 0.9rem;
  min-height: 30rem;
  padding: 0.6rem 0 0.2rem;
  color: rgba(216, 216, 232, 0.86);
  transition:
    border-color 160ms ease,
    background 160ms ease;
