  background: rgba(135, 87, 255, 0.08);
  box-shadow: inset 0 0 0 1px rgba(166, 112, 255, 0.34);
}

.stage-image-group {
  display: grid;
  gap: 0.7rem;
}

.stage-image-library-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  color: #fff;
  font-size: 0.96rem;
  font-weight: 800;
}

.stage-image-library-head strong,
.stage-video-group-head strong {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.stage-image-library-head strong span,
.stage-video-group-head strong span {
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.72rem;
}

.stage-image-preview-card {
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, auto);
  gap: 0.8rem;
  align-content: start;
  width: 100%;
  max-width: 19rem;
  min-width: 0;
  min-height: 0;
  padding: 0.85rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1rem;
  background: rgba(10, 11, 16, 0.92);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
  overflow: hidden;
}

.stage-image-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  align-items: stretch;
  gap: 0.75rem;
}

.stage-image-preview-surface {
  position: relative;
  isolation: isolate;
  width: 100%;
  aspect-ratio: 16 / 9;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 0.8rem;
