@keyframes asset-generation-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(87, 204, 255, 0.44);
  }
  100% {
    box-shadow: 0 0 0 0.55rem rgba(87, 204, 255, 0);
  }
}

.asset-card-menu-button {
  display: grid;
  width: 2.2rem;
  height: 2.2rem;
  flex: 0 0 2.2rem;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 0.7rem;
  background: rgba(31, 33, 43, 0.84);
  color: rgba(255, 255, 255, 0.88);
  font-size: 1.15rem;
  opacity: 0;
  pointer-events: none;
  transform: translateY(0.2rem);
  transition:
    opacity 160ms ease,
    transform 160ms ease,
    background 160ms ease;
}

.imported-asset-card:hover .asset-card-menu-button,
.other-imported-card:hover .asset-card-menu-button,
.imported-asset-card:focus-within .asset-card-menu-button,
.other-imported-card:focus-within .asset-card-menu-button,
.asset-card-menu-button[aria-expanded="true"] {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.asset-card-menu-button:hover,
.asset-card-menu-button:focus-visible {
  background: rgba(43, 46, 59, 0.96);
}

.asset-card-menu {
  position: absolute;
  right: 0.7rem;
  bottom: 3rem;
  z-index: 3;
  display: grid;
  gap: 0.25rem;
  min-width: 8.75rem;
  padding: 0.45rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.95rem;
  background: rgba(26, 27, 36, 0.98);
  box-shadow: 0 1rem 2.4rem rgba(0, 0, 0, 0.35);
}

.asset-card-menu-item {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  justify-content: flex-start;
  width: 100%;
  min-height: 2.2rem;
  padding: 0 0.8rem;
  border: 0;
  border-radius: 0.7rem;
  background: transparent;
  color: rgba(255, 255, 255, 0.92);
  font-size: 0.9rem;
  text-align: left;
}

.asset-card-menu-item span {
  display: inline-grid;
  width: 0.95rem;
  place-items: center;
  color: currentColor;
  font-size: 0.9rem;
}

.asset-card-menu-item:hover,
.asset-card-menu-item:focus-visible {
  background: rgba(255, 255, 255, 0.08);
}

.asset-card-menu-item.danger {
  color: #ff8f8f;
}

.asset-preview-placeholder {
  display: grid;
  width: 100%;
  height: 100%;
  min-height: 8rem;
  place-items: center;
  color: rgba(255, 255, 255, 0.68);
  font-size: 1.6rem;
}

.imported-asset-meta {
  padding: 0 0.15rem 0.05rem;
}

.imported-asset-meta strong,
.other-imported-card strong {
  font-size: 0.92rem;
  font-weight: 900;
}

.asset-card-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem;
  padding: 0 0.15rem 0.05rem;
}

.asset-card-copy {
  display: grid;
  gap: 0.22rem;
  min-width: 0;
}

.asset-card-meta-row strong {
  display: block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.asset-card-copy span {
  display: block;
  max-width: 100%;
  overflow: hidden;
  color: rgba(255, 255, 255, 0.56);
  font-size: 0.78rem;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-info-panel {
  display: block;
}

.project-stats-dashboard {
  --stats-ink: #f2f7f6;
  --stats-muted: rgba(220, 231, 229, 0.58);
  --stats-line: rgba(189, 211, 207, 0.12);
  --stats-cyan: #64e6d3;
  --stats-amber: #f2c96d;
  --stats-coral: #ed8f7b;
  flex-shrink: 0;
  height: max-content;
  min-height: 100%;
  overflow: hidden;
  color: var(--stats-ink);
  background-color: #0d1518;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.018) 1px, transparent 1px);
  background-size: 2.25rem 2.25rem;
}

.project-stats-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(17rem, 1.1fr) minmax(25rem, 1.45fr) 11rem;
  gap: 2rem;
  align-items: center;
  min-height: 18.5rem;
  padding: 2.6rem 3rem;
  border-bottom: 1px solid var(--stats-line);
  background: linear-gradient(112deg, rgba(23, 48, 49, 0.94), rgba(14, 26, 30, 0.96) 55%, rgba(30, 28, 29, 0.94));
}

.project-stats-hero::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  width: 32%;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--stats-amber));
  content: "";
}

.project-stats-hero-copy {
  display: grid;
  gap: 0.65rem;
  align-content: center;
}

.project-stats-kicker,
.project-stats-section-heading > div > span {
  color: var(--stats-cyan);
  font-family: "Bahnschrift", "Microsoft YaHei", sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0;
}

.project-stats-hero-copy h1 {
  margin: 0;
  font-family: "Microsoft YaHei UI", "Microsoft YaHei", sans-serif;
  font-size: 2.35rem;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: 0;
}

.project-stats-hero-copy > p {
  max-width: 25rem;
  margin: 0;
  color: var(--stats-muted);
  font-size: 0.86rem;
  line-height: 1.65;
}

.project-stats-status-line {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem 0.6rem;
  align-items: center;
  margin-top: 0.65rem;
}

.project-stats-status-line i {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: var(--stats-cyan);
  box-shadow: 0 0 0 0.26rem rgba(100, 230, 211, 0.12);
}

.project-stats-status-line strong {
  color: var(--stats-ink);
  font-size: 0.78rem;
}

.project-stats-status-line span {
  color: var(--stats-muted);
  font-size: 0.75rem;
}

.project-stats-hero-figures {
  display: grid;
  grid-template-columns: repeat(3, minmax(7rem, 1fr));
  gap: 0.65rem;
}

.project-stats-hero .project-info-card.stat-card {
  display: flex;
  gap: 0.72rem;
  align-items: flex-start;
  min-width: 0;
  min-height: 7.8rem;
  padding: 1rem 0.85rem;
  border: 1px solid rgba(216, 232, 229, 0.1);
  border-radius: 6px;
  background: rgba(7, 15, 18, 0.34);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.project-stat-metric-icon {
  display: grid;
  flex: 0 0 2rem;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border: 1px solid rgba(100, 230, 211, 0.16);
  border-radius: 5px;
  color: var(--stats-cyan);
  background: rgba(100, 230, 211, 0.07);
}

.project-stat-metric-icon svg,
.project-production-stage-icon svg,
.project-stat-signal-icon svg,
.project-delivery-figure svg {
  width: 1.1rem;
  height: 1.1rem;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.6;
}

.project-stats-hero .stat-card > div {
  display: grid;
  gap: 0.25rem;
  min-width: 0;
}

.project-stats-hero .stat-card > div > span {
  color: var(--stats-muted);
  font-size: 0.74rem;
  font-weight: 700;
}

.project-stats-hero .stat-card > div > strong {
  margin-top: 0.35rem;
  color: var(--stats-ink);
  font-family: "Bahnschrift", "Microsoft YaHei", sans-serif;
  font-size: 2rem;
  font-weight: 700;
  line-height: 1;
}

.project-stats-hero .stat-card > div > small {
  overflow: hidden;
  color: var(--stats-muted);
  font-size: 0.68rem;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-stats-ring {
  position: relative;
  display: grid;
  place-items: center;
  width: 10.5rem;
  height: 10.5rem;
  border-radius: 50%;
  background: conic-gradient(var(--stats-amber) calc(var(--project-progress) * 1%), rgba(255, 255, 255, 0.08) 0);
  box-shadow: 0 1.2rem 3rem rgba(0, 0, 0, 0.22);
}

.project-stats-ring::before {
  position: absolute;
  width: 8.15rem;
  height: 8.15rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 50%;
  background: #172023;
  content: "";
}

.project-stats-ring > div {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 0.25rem;
  justify-items: center;
}

.project-stats-ring strong {
  font-family: "Bahnschrift", "Microsoft YaHei", sans-serif;
  font-size: 2.45rem;
  line-height: 1;
}

.project-stats-ring strong small {
  margin-left: 0.1rem;
  color: var(--stats-amber);
  font-size: 0.9rem;
}

.project-stats-ring span {
  color: var(--stats-muted);
  font-size: 0.72rem;
}

.project-stats-content {
  display: grid;
  grid-template-columns: minmax(0, 2.4fr) minmax(14rem, 0.8fr);
  border-bottom: 1px solid var(--stats-line);
}

.project-stats-production,
.project-stats-delivery,
.project-stats-efficiency {
  min-width: 0;
  padding: 2rem 3rem;
}

.project-stats-delivery {
  border-left: 1px solid var(--stats-line);
  background: rgba(5, 12, 14, 0.3);
}

.project-stats-section-heading {
  display: flex;
  gap: 1rem;
  align-items: end;
  justify-content: space-between;
  margin-bottom: 1.75rem;
}

.project-stats-section-heading h2 {
  margin: 0.22rem 0 0;
  font-size: 1.05rem;
  font-weight: 750;
  letter-spacing: 0;
}

.project-stats-section-heading > p {
  margin: 0;
  color: var(--stats-muted);
  font-size: 0.72rem;
}

.project-production-flow {
  display: grid;
  grid-template-columns: repeat(4, minmax(7rem, 1fr));
  gap: 0;
}

.project-production-stage {
  position: relative;
  display: grid;
  grid-template-columns: 2.35rem minmax(0, 1fr);
  gap: 0.75rem;
  min-width: 0;
  padding: 0 1rem 1.35rem 0;
}

.project-production-stage:not(:last-child)::after {
  position: absolute;
  top: 1.12rem;
  right: 0.2rem;
  width: calc(100% - 3.4rem);
  height: 1px;
  background: linear-gradient(90deg, rgba(100, 230, 211, 0.22), rgba(242, 201, 109, 0.16));
  content: "";
}

.project-production-stage-icon {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 2.35rem;
  height: 2.35rem;
  border: 1px solid rgba(100, 230, 211, 0.22);
  border-radius: 6px;
  color: var(--stats-cyan);
  background: #142326;
}

.project-production-stage-copy {
  display: grid;
  gap: 0.18rem;
  min-width: 0;
}

.project-production-stage-copy > span,
.project-production-stage-copy > small {
  overflow: hidden;
  color: var(--stats-muted);
  font-size: 0.7rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-production-stage-copy > strong {
  font-family: "Bahnschrift", "Microsoft YaHei", sans-serif;
  font-size: 1.65rem;
  line-height: 1.1;
}

.project-production-stage-track {
  grid-column: 1 / -1;
  height: 3px;
  overflow: hidden;
  margin-top: 0.7rem;
  background: rgba(255, 255, 255, 0.07);
}

.project-production-stage-track i {
  display: block;
  width: calc(var(--stage-progress) * 1%);
  height: 100%;
  background: linear-gradient(90deg, var(--stats-cyan), var(--stats-amber));
  transform-origin: left;
  animation: project-stat-track-in 640ms ease-out both;
}

@keyframes project-stat-track-in {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}

.project-delivery-figure {
  display: grid;
  grid-template-columns: 2.5rem 1fr;
  align-items: center;
  margin-top: 0.5rem;
}

.project-delivery-figure > span {
  display: grid;
  place-items: center;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 6px;
  color: #171a19;
  background: var(--stats-amber);
}

.project-delivery-figure > strong {
  margin-left: 0.75rem;
  font-family: "Bahnschrift", "Microsoft YaHei", sans-serif;
  font-size: 2.6rem;
  line-height: 1;
}

.project-delivery-figure > p {
  grid-column: 2;
  margin: -0.25rem 0 0 0.75rem;
  color: var(--stats-muted);
  font-size: 0.72rem;
}

.project-delivery-meta {
  display: grid;
  gap: 0.25rem;
  margin-top: 1.75rem;
  padding-top: 1rem;
  border-top: 1px solid var(--stats-line);
}

.project-delivery-meta span {
  color: var(--stats-muted);
  font-size: 0.68rem;
}

.project-delivery-meta strong {
  font-size: 0.8rem;
  font-weight: 650;
}

.project-stats-efficiency {
  display: grid;
  grid-template-columns: minmax(11rem, 0.65fr) minmax(0, 2.35fr);
  gap: 2rem;
  align-items: center;
}

.project-stats-efficiency .project-stats-section-heading {
  margin-bottom: 0;
}

.project-stats-signal-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(8rem, 1fr));
}

.project-stat-signal {
  display: flex;
  gap: 0.7rem;
  align-items: center;
  min-width: 0;
  padding: 0.35rem 1.2rem;
  border-left: 1px solid var(--stats-line);
}

.project-stat-signal-icon {
  display: grid;
  flex: 0 0 2rem;
  place-items: center;
  width: 2rem;
  height: 2rem;
  color: var(--stats-coral);
}

.project-stat-signal > div {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
}

.project-stat-signal > div > span {
  color: var(--stats-muted);
  font-size: 0.68rem;
}

.project-stat-signal > div > strong {
  font-family: "Bahnschrift", "Microsoft YaHei", sans-serif;
  font-size: 1.15rem;
  line-height: 1;
}

.project-stat-signal > div > strong small {
  margin-left: 0.28rem;
  color: var(--stats-muted);
  font-family: "Microsoft YaHei UI", "Microsoft YaHei", sans-serif;
  font-size: 0.62rem;
  font-weight: 500;
}

@media (prefers-reduced-motion: reduce) {
  .project-production-stage-track i {
    animation: none;
  }
}

@media (max-width: 1180px) {
  .project-stats-hero {
    grid-template-columns: minmax(15rem, 1fr) minmax(22rem, 1.25fr);
  }

  .project-stats-ring {
    display: none;
  }
}

@media (max-width: 900px) {
  .project-stats-hero {
    grid-template-columns: 1fr;
    gap: 1.5rem;
    padding: 2rem;
  }

  .project-stats-content,
  .project-stats-efficiency {
    grid-template-columns: 1fr;
  }

  .project-stats-delivery {
    border-top: 1px solid var(--stats-line);
    border-left: 0;
  }

  .project-stats-signal-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 1.5rem;
  }

  .project-stats-production,
  .project-stats-delivery,
  .project-stats-efficiency {
    padding: 1.75rem 2rem;
  }
}

@media (max-width: 620px) {
  .project-stats-hero {
    padding: 1.6rem 1.2rem;
  }

  .project-stats-hero-copy h1 {
    font-size: 1.8rem;
  }

  .project-stats-hero-figures {
    grid-template-columns: 1fr;
  }

  .project-stats-hero .project-info-card.stat-card {
    min-height: 5.4rem;
  }

  .project-production-flow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1.25rem 0;
  }

  .project-stats-production,
  .project-stats-delivery,
  .project-stats-efficiency {
    padding: 1.5rem 1.2rem;
  }

  .project-stats-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .project-stats-signal-grid {
    grid-template-columns: 1fr;
  }

  .project-stat-signal {
    padding-left: 0;
    border-left: 0;
  }

}

.other-asset-library {
  --other-library-card-width: 11.5rem;
  --other-library-card-height: 14.9rem;
  display: grid;
  grid-template-columns: var(--other-library-card-width) minmax(0, 1fr);
  gap: 0.85rem;
  align-items: start;
  height: 100%;
  min-height: 0;
  padding: 0;
}

.other-asset-library > :not(.seedance-import-card) {
  min-width: 0;
}

.other-asset-library .other-imported-card {
  width: 100%;
}

.asset-library-content-grid.other-grid-mode {
  grid-template-columns: repeat(auto-fill, var(--other-library-card-width));
  grid-auto-rows: var(--other-library-card-height);
  justify-content: start;
  align-content: start;
}

.other-imported-play {
  position: absolute;
  inset: 50% auto auto 50%;
  transform: translate(-50%, -50%);
  display: grid;
  width: 3rem;
  height: 3rem;
  place-items: center;
  border-radius: 999px;
  background: rgba(10, 11, 16, 0.58);
  color: #fff;
  font-size: 1.1rem;
}

.other-imported-badge {
  position: absolute;
  left: 0.9rem;
  top: 0.9rem;
  padding: 0.3rem 0.55rem;
  border-radius: 999px;
  background: rgba(26, 28, 36, 0.82);
  color: rgba(255, 255, 255, 0.92);
  font-size: 0.72rem;
  font-weight: 800;
}

.other-imported-card.audio {
  grid-template-rows: auto auto;
  height: var(--other-library-card-height);
  min-height: var(--other-library-card-height);
  padding: 0.42rem;
}

.other-imported-preview.audio-preview {
  display: grid;
  align-items: end;
  min-height: 0;
  padding: 0.68rem;
  aspect-ratio: 1 / 1;
  background:
    linear-gradient(0deg, rgba(16, 18, 26, 0.26), rgba(16, 18, 26, 0.08)),
    linear-gradient(45deg, rgba(255, 255, 255, 0.06) 25%, transparent 25%, transparent 75%, rgba(255, 255, 255, 0.06) 75%, rgba(255, 255, 255, 0.06)),
    linear-gradient(45deg, rgba(255, 255, 255, 0.06) 25%, transparent 25%, transparent 75%, rgba(255, 255, 255, 0.06) 75%, rgba(255, 255, 255, 0.06));
  background-position:
    0 0,
    0 0,
    0.65rem 0.65rem;
  background-size:
    100% 100%,
    1.3rem 1.3rem,
    1.3rem 1.3rem;
  background-color: rgba(241, 244, 252, 0.08);
}

.other-imported-preview.audio-preview.has-cover {
  padding: 0;
}

.other-imported-preview.audio-preview.has-cover img {
  position: absolute;
  inset: 0;
}

.project-audio-avatar {
  justify-self: center;
  align-self: center;
  width: min(6.8rem, 58%);
  height: auto;
  aspect-ratio: 0.86;
  border-radius: 999px 999px 1.2rem 1.2rem;
  background:
    radial-gradient(circle at 50% 18%, rgba(255, 255, 255, 0.12) 0.45rem, transparent 0.46rem),
    linear-gradient(180deg, rgba(33, 37, 52, 0.96), rgba(24, 27, 39, 0.98));
  box-shadow:
    inset 0 -0.6rem 0 rgba(255, 255, 255, 0.02),
    0 1rem 2rem rgba(0, 0, 0, 0.2);
  clip-path: polygon(30% 0%, 70% 0%, 80% 10%, 80% 34%, 74% 42%, 74% 52%, 82% 58%, 86% 72%, 86% 100%, 14% 100%, 14% 72%, 18% 58%, 26% 52%, 26% 42%, 20% 34%, 20% 10%);
}

.project-audio-card-actions {
  position: absolute;
  left: 50%;
  bottom: 0.85rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 0.4rem);
  transition:
    opacity 180ms ease,
    transform 180ms ease;
}

.other-imported-card.audio:hover .project-audio-card-actions,
.other-imported-card.audio:focus-within .project-audio-card-actions {
  opacity: 1;
  pointer-events: auto;
  transform: translate(-50%, 0);
}

.project-audio-play-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--theme-control-active-border, rgba(255, 255, 255, 0.18));
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 32%, rgba(255, 255, 255, 0.18), transparent 56%),
    rgba(12, 14, 20, 0.88);
  color: var(--theme-control-active-text, #ffffff);
  box-shadow:
    0 0.55rem 1.3rem rgba(0, 0, 0, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
  backdrop-filter: blur(12px);
}

.project-audio-play-button {
  width: 2.5rem;
  height: 2.5rem;
  padding: 0;
  cursor: pointer;
}

.project-audio-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.project-audio-icon-play {
  width: 0;
  height: 0;
  margin-left: 0.2rem;
  overflow: hidden;
  border-block: 0.42rem solid transparent;
  border-left: 0.68rem solid currentColor;
  color: #ffffff;
  font-size: 0;
  line-height: 0;
}

.project-audio-icon-pause {
  gap: 0.24rem;
  color: #ffffff;
}

.project-audio-icon-pause span {
  display: block;
  width: 0.2rem;
  height: 0.8rem;
  border-radius: 999px;
  background: currentColor;
}

.project-audio-play-button:hover,
.project-audio-play-button:focus-visible {
  background:
