    grid-template-rows: auto auto auto auto;
    min-height: auto;
    height: auto;
  }

  .cinematic-layout .episode-workbench-utility-bar,
  .cinematic-layout .shot-sidebar-hero,
  .cinematic-layout .episode-media-header,
  .cinematic-layout .cinematic-sidebar,
  .cinematic-layout .cinematic-stage,
  .cinematic-layout .director-console {
    grid-column: 1;
    grid-row: auto;
  }

  .cinematic-layout .shot-stack {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cinematic-layout .cinematic-sidebar,
  .cinematic-layout .cinematic-stage,
  .cinematic-layout .director-console {
    min-height: auto;
  }
}

.cinematic-layout {
