/* Episode workbench ratio tune: mirror reference screenshot */
.episode-replica-layout {
  grid-template-columns: var(--episode-replica-left-width) var(--episode-replica-center-width) var(--episode-replica-right-width);
  gap: 0;
  min-width: 0;
}

.episode-replica-left {
