.episode-replica-task-refs.asset-inline {
  margin-top: 0.5rem;
}

.episode-replica-task-status {
  display: inline-flex;
  align-items: center;
  min-height: 1.38rem;
  padding: 0 0.48rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.74);
  font-size: 0.72rem;
  font-weight: 800;
}

.episode-replica-task-copy {
  max-width: 100%;
  color: rgba(255, 255, 255, 0.96);
  font-size: 0.88rem;
  font-weight: 800;
  line-height: 1.34;
  text-align: left;
  word-break: break-word;
}

.episode-replica-task-copy.clamp-3 {
  display: -webkit-box;
