.episode-replica-task-status.running,
.episode-replica-task-status.pending,
.episode-replica-task-status.queued {
  background: rgba(255, 183, 77, 0.16);
  color: #ffd08a;
}

.episode-replica-task-status.completed,
.episode-replica-task-status.succeeded {
  background: rgba(103, 214, 159, 0.16);
  color: #8df0b8;
}

.episode-replica-task-status.failed {
  background: rgba(255, 107, 107, 0.16);
  color: #ff9a9a;
}

.episode-replica-progress-box {
  display: grid;
  gap: 0.55rem;
  margin-top: 0.7rem;
  padding: 0.8rem 0.9rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.85rem;
  background: rgba(18, 19, 22, 0.56);
}

.episode-replica-progress-track {
