.episode-replica-right-panel {
  width: 100%;
  height: 100%;
  max-height: 100%;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.episode-replica-right-toggle {
  position: absolute;
  top: 0.42rem;
  right: 0.28rem;
  z-index: 20;
  display: grid;
  place-items: center;
  width: 2.7rem;
  min-width: 2.7rem;
  height: 2.7rem;
  min-height: 2.7rem;
  padding: 0;
  border: 1px solid rgba(173, 118, 255, 0.72);
  border-radius: 999px;
  background:
    linear-gradient(135deg, #8b5cff 0%, #c968ff 52%, #4fd8ff 100%);
  color: rgba(255, 255, 255, 0.98);
  box-shadow:
    0 0.8rem 1.8rem rgba(96, 79, 255, 0.26),
    0 0 0 1px rgba(255, 255, 255, 0.08) inset;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    color 160ms ease,
    transform 160ms ease;
}

.episode-replica-right-toggle::before,
.episode-replica-right-toggle::after {
  position: absolute;
  right: calc(100% + 0.72rem);
  opacity: 0;
  pointer-events: none;
  transition:
    opacity 160ms ease,
    transform 160ms ease;
}

.episode-replica-right-toggle::before {
  content: attr(data-tooltip);
  top: 50%;
  min-width: max-content;
  max-width: 11rem;
  padding: 0.62rem 0.9rem;
  border: 1px solid rgba(173, 118, 255, 0.5);
  border-radius: 0.9rem;
  background: rgba(14, 10, 32, 0.96);
  color: rgba(255, 255, 255, 0.98);
  font-size: 0.9rem;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0;
  white-space: nowrap;
  box-shadow:
    0 1rem 2.4rem rgba(45, 18, 94, 0.42),
    0 0 0 1px rgba(255, 255, 255, 0.06) inset;
  transform: translate3d(0.4rem, -50%, 0) scale(0.96);
}

.episode-replica-right-toggle::after {
  content: "";
  top: 50%;
  width: 0.7rem;
  height: 0.7rem;
  border-top: 1px solid rgba(173, 118, 255, 0.5);
  border-right: 1px solid rgba(173, 118, 255, 0.5);
  background: rgba(14, 10, 32, 0.96);
  box-shadow: 0.35rem -0.35rem 0.8rem rgba(45, 18, 94, 0.16);
  transform: translate3d(0.18rem, -50%, 0) rotate(45deg) scale(0.96);
}

.episode-replica-right-toggle:hover {
  border-color: rgba(173, 118, 255, 0.96);
  background:
    linear-gradient(135deg, #9968ff 0%, #d772ff 50%, #67deff 100%);
  color: rgba(255, 255, 255, 1);
  box-shadow:
    0 1rem 2rem rgba(111, 90, 255, 0.32),
    0 0 0 1px rgba(255, 255, 255, 0.12) inset;
  transform: translateY(-1px);
}

.episode-replica-right-toggle:hover::before,
.episode-replica-right-toggle:hover::after,
.episode-replica-right-toggle:focus-visible::before,
.episode-replica-right-toggle:focus-visible::after {
  opacity: 1;
}

.episode-replica-right-toggle:hover::before,
.episode-replica-right-toggle:focus-visible::before {
  transform: translate3d(0, -50%, 0) scale(1);
}

.episode-replica-right-toggle:hover::after,
.episode-replica-right-toggle:focus-visible::after {
  transform: translate3d(0, -50%, 0) rotate(45deg) scale(1);
}

.episode-replica-right-toggle:focus-visible {
  outline: 2px solid rgba(145, 214, 255, 0.72);
  outline-offset: 2px;
}

.episode-replica-right-toggle.is-collapse {
  width: 2.7rem;
  min-width: 2.7rem;
  height: 2.7rem;
  min-height: 2.7rem;
}

.episode-replica-right-toggle-collapse-icon {
  position: relative;
  display: block;
  width: 1.14rem;
  height: 1.14rem;
}

.episode-replica-right-toggle-collapse-bars {
  position: absolute;
  left: 0;
  top: 50%;
  display: grid;
  gap: 0.12rem;
  transform: translateY(-50%);
}

.episode-replica-right-toggle-collapse-bars span {
  display: block;
  width: 0.52rem;
  height: 0.12rem;
  border-radius: 999px;
  background: currentColor;
  opacity: 0.92;
}

.episode-replica-right-toggle-collapse-bars span:nth-child(2) {
  width: 0.66rem;
}

.episode-replica-right-toggle-collapse-bars span:nth-child(3) {
  width: 0.44rem;
}

.episode-replica-right-toggle-collapse-chevron {
  position: absolute;
  right: 0.03rem;
  top: 50%;
  display: block;
  width: 0.38rem;
  height: 0.38rem;
  border-right: 2px solid currentColor;
  border-top: 2px solid currentColor;
  opacity: 0.84;
  transform: translateY(-50%) rotate(45deg);
  transform-origin: center;
}

.episode-replica-right.is-collapsed {
  width: 0;
  min-width: 0;
  padding-left: 0;
  padding-right: 0;
  overflow: visible;
}

.episode-replica-right.is-collapsed .episode-replica-right-toggle {
