  grid-template-rows: auto minmax(0, 1fr);
  gap: 1.15rem;
  width: min(78rem, calc(100vw - 4rem));
  min-height: min(46rem, calc(100vh - 3rem));
  max-height: min(58rem, calc(100vh - 3rem));
  padding: 1.8rem 1.8rem 1.5rem;
  overflow: hidden;
  border: 1px solid var(--theme-control-border);
  border-radius: 1.35rem;
  background:
    radial-gradient(circle at 82% 0%, var(--theme-accent-soft), transparent 22rem),
    var(--theme-panel-background);
  color: var(--text-primary, #ffffff);
  box-shadow: 0 2rem 6rem var(--theme-statusbar-shadow, rgba(0, 0, 0, 0.52));
}

.episode-asset-library-head {
  display: grid;
  gap: 1rem;
  padding-right: 2.8rem;
}

.episode-asset-library-head h2 {
  margin: 0;
  color: var(--text-primary, #ffffff);
  font-size: 1.4rem;
  font-weight: 900;
  letter-spacing: 0;
}

.episode-asset-library-title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1.4rem;
  min-width: 0;
}

.episode-asset-library-scope-tabs {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  max-width: 100%;
  min-width: 0;
  overflow-x: auto;
  padding: 0.28rem;
  border: 1px solid var(--theme-control-border);
  border-radius: 0.65rem;
  background: var(--theme-muted-background);
  scrollbar-width: none;
}

.episode-asset-library-scope-tabs::-webkit-scrollbar {
  display: none;
}

.episode-asset-library-scope-tabs button {
  min-width: 7rem;
  min-height: 2.35rem;
  padding: 0 1rem;
  border: 0;
  border-radius: 0.45rem;
  background: transparent;
  color: var(--text-muted, rgba(255, 255, 255, 0.64));
  font: inherit;
  font-weight: 800;
  white-space: nowrap;
}

.episode-asset-library-scope-tabs button:hover {
  background: var(--theme-control-hover-background);
  color: var(--text-primary, #fff);
}

.episode-asset-library-scope-tabs button.active {
  background: var(--theme-control-active-background);
  color: var(--theme-control-active-text, #fff);
  box-shadow: inset 0 0 0 1px var(--theme-control-active-border);
}

.episode-asset-library-tabs {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.28rem;
  border-radius: 999px;
  border: 1px solid var(--theme-control-border);
  background: var(--theme-muted-background);
}

.episode-asset-library-tabs button {
  min-width: 5rem;
  min-height: 2.35rem;
  padding: 0 1rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-muted, rgba(255, 255, 255, 0.64));
  font: inherit;
  font-weight: 800;
}

.episode-asset-library-tabs button.active {
  background: var(--theme-accent-gradient);
  color: var(--theme-control-active-text, #ffffff);
}

.episode-asset-library-body {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 1rem;
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

.episode-asset-library-body.empty {
  grid-template-rows: minmax(0, 1fr) auto;
}

.episode-asset-library-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.65rem;
  min-height: 0;
  overflow-y: auto;
  padding-right: 0.2rem;
  align-content: start;
}

.episode-asset-library-card {
  display: grid;
  gap: 0.4rem;
  padding: 0.45rem 0.45rem 0.5rem;
  border: 1px solid var(--theme-control-border);
  border-radius: 0.8rem;
  background: var(--theme-control-background);
  color: var(--text-primary, #ffffff);
  text-align: center;
}

.episode-asset-library-card:hover {
  border-color: var(--theme-control-hover-border);
  background: var(--theme-control-hover-background);
}

.episode-asset-library-card.selected {
  border-color: var(--theme-control-active-border);
  box-shadow: 0 0 0 1px var(--theme-accent-soft);
}

.episode-asset-library-check {
  display: grid;
  width: 0.9rem;
  height: 0.9rem;
  place-self: start;
  border-radius: 999px;
  background: var(--theme-muted-background);
  box-shadow: inset 0 0 0 1px var(--theme-control-hover-border);
}

.episode-asset-library-check.selected {
  background: var(--theme-accent-gradient);
  box-shadow: inset 0 0 0 3px var(--theme-control-border);
}

.episode-asset-library-thumb {
  display: block;
  overflow: hidden;
  aspect-ratio: 1 / 1;
  border-radius: 0.65rem;
  background: var(--theme-muted-background);
}

.episode-asset-library-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.episode-asset-library-card strong {
  display: block;
  color: var(--text-primary, #ffffff);
  font-size: 0.76rem;
  font-weight: 900;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.episode-asset-library-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-top: auto;
  padding-top: 0.8rem;
  border-top: 1px solid var(--theme-control-border);
  background: var(--theme-panel-background);
  flex-shrink: 0;
}

.episode-asset-library-footer.empty {
  justify-content: flex-end;
}

.episode-asset-library-pagination {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  color: var(--text-muted, rgba(255, 255, 255, 0.68));
  font-size: 0.86rem;
  font-weight: 700;
}

.episode-asset-library-page-size-wrap {
  position: relative;
}

.episode-asset-library-page-size {
  min-height: 2.25rem;
  padding: 0 0.9rem;
  border: 1px solid var(--theme-control-border);
  border-radius: 0.75rem;
  background: var(--theme-control-background);
  color: var(--text-primary, #ffffff);
  font: inherit;
  font-weight: 800;
}

.episode-asset-library-page-size-menu {
  position: absolute;
  top: calc(100% + 0.35rem);
  left: 0;
  z-index: 8;
  display: grid;
  min-width: 6.25rem;
  padding: 0.35rem;
  border: 1px solid var(--theme-control-border);
  border-radius: 0.8rem;
  background: var(--theme-panel-background);
  box-shadow: 0 1.2rem 3rem var(--theme-statusbar-shadow, rgba(0, 0, 0, 0.35));
}

.episode-asset-library-page-size-menu button,
.episode-asset-library-page-controls button {
  min-height: 2.15rem;
  padding: 0 0.75rem;
  border: 0;
  border-radius: 0.65rem;
  background: transparent;
  color: var(--text-muted, rgba(255, 255, 255, 0.78));
  font: inherit;
  font-weight: 800;
}

.episode-asset-library-page-size-menu button:hover,
.episode-asset-library-page-controls button:hover:not(:disabled) {
  background: var(--theme-control-hover-background);
  color: var(--text-primary, #ffffff);
}

.episode-asset-library-page-controls {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.episode-asset-library-page-controls button:disabled {
  opacity: 0.4;
}

.episode-asset-library-page-controls em {
  display: grid;
  min-width: 2.1rem;
  min-height: 2.1rem;
  place-items: center;
  border-radius: 999px;
  background: var(--theme-accent-gradient);
  color: var(--theme-control-active-text, #ffffff);
  font-style: normal;
  font-weight: 900;
}

.episode-asset-library-empty {
  display: grid;
  flex: 1 1 auto;
  min-height: 26rem;
  place-items: center;
  align-content: center;
  gap: 0.85rem;
  border-radius: 1rem;
  border: 1px solid var(--theme-control-border);
  background: var(--theme-control-background);
  color: var(--text-muted, rgba(255, 255, 255, 0.72));
  text-align: center;
}

.episode-asset-library-empty .asset-import-lock {
  display: grid;
  width: 3.2rem;
  height: 3.2rem;
  place-items: center;
  border-radius: 1rem;
  background: var(--theme-muted-background);
  color: var(--theme-accent-icon, #c9ccd6);
  font-size: 1.35rem;
}

.episode-asset-library-empty strong {
  color: var(--text-primary, #ffffff);
  font-size: 1rem;
  font-weight: 900;
}

@media (max-width: 1100px) {
  .episode-batch-config-grid,
  .episode-batch-video-config-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .episode-batch-footer.image-composer {
    align-items: stretch;
    flex-direction: column;
  }

  .episode-batch-footer-controls {
    flex-wrap: wrap;
  }

  .episode-batch-select-group.compact {
    min-width: min(100%, 18rem);
  }

  .episode-batch-settings-panel {
    left: auto;
    right: 0;
  }
}

@media (max-width: 720px) {
