  }

  .episode-replica-topbar-left,
  .episode-replica-topbar-center,
  .episode-replica-topbar-right {
    width: 100%;
    justify-content: flex-start;
    flex-wrap: wrap;
    gap: 0.45rem;
  }

  .episode-replica-timestamp {
    max-width: none;
  }

  .episode-replica-main-switch {
