  }

  .episode-replica-right-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .episode-replica-shot-card-body {
    grid-template-columns: minmax(0, 0.88fr) minmax(0, 1fr) minmax(0, 0.7fr);
  }

  .episode-hub-shell.populated {
    padding: 0.88rem 0.95rem 1.08rem;
  }

  .episode-hub-shell.populated .episode-hub-grid {
    grid-template-columns: 1fr;
  }

  .episode-hub-shell.populated .episode-hub-launches {
    display: grid;
