  }

  .episode-replica-textarea .magic {
    top: 0.4rem;
    right: 0.48rem;
    width: 1.62rem;
    height: 1.62rem;
  }

  .episode-replica-textarea em {
    right: 0.48rem;
    bottom: 0.42rem;
    font-size: 0.66rem;
  }

  .episode-replica-generate {
    min-width: 6.1rem;
    min-height: 2.08rem;
    padding: 0 0.58rem;
  }

  .episode-replica-right {
    padding: 0.02rem 0.68rem 0.56rem;
  }

  .episode-replica-right-search {
