  }

  .episode-hub-shell.populated .episode-launch-copy h2,
  .episode-hub-shell.populated .episode-launch-card.single .episode-launch-copy h2 {
    font-size: 0.88rem;
  }

  .episode-hub-shell.populated {
    padding: 0.72rem 0.78rem 0.84rem;
  }

  .episode-replica-stage-actions {
    flex-wrap: wrap;
    gap: 0.22rem;
  }

  .episode-replica-stage-actions button {
    min-height: 1.66rem;
    padding-inline: 0.44rem;
