/* Final mobile overrides: keep last to beat earlier duplicated compact rules */
@media (max-width: 640px) {
  .episode-replica-layout.storyboard-mode .episode-replica-storyboard-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 0.62rem;
    overflow: visible;
    overflow-x: visible;
    overflow-y: visible;
    padding-bottom: 0;
    scroll-snap-type: none;
  }

  .episode-replica-layout.storyboard-mode .episode-replica-shot-shell,
  .episode-replica-layout.storyboard-mode .episode-replica-shot-card,
  .episode-replica-layout.storyboard-mode .episode-replica-storyboard-empty {
    width: 100%;
    min-width: 0;
    max-width: 100%;
    flex: initial;
    scroll-snap-align: none;
  }

  .episode-replica-layout.storyboard-mode .episode-replica-shot-card-body {
    grid-template-columns: 1fr;
  }

  .episode-replica-left {
    max-height: 52vh;
    overflow: auto;
    overscroll-behavior: contain;
    padding-bottom: 0.4rem;
  }

  .episode-replica-right {
    max-height: 24rem;
    overflow: auto;
    overscroll-behavior: contain;
  }
}

/* Final left-pane asset list rules: keep these last to beat duplicated workbench styles above */
.episode-replica-left {
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  min-height: 0;
  align-content: flex-start;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.episode-replica-left::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}

.episode-replica-asset-toolbar.unified {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  flex: 0 0 auto;
  min-height: auto;
  height: auto;
  gap: 0.9rem;
}

.episode-replica-asset-toolbar.unified .episode-replica-asset-toolbar-head {
  position: sticky;
  top: 0;
  z-index: 5;
  flex: 0 0 auto;
  background: transparent;
}

.episode-replica-asset-sections {
  position: relative;
  display: grid;
  align-content: start;
  gap: 1.7rem;
  min-height: auto;
  overflow: visible;
  scroll-margin-top: 4.1rem;
  padding-bottom: 1rem;
}

.episode-replica-asset-section {
  display: block;
  min-height: auto;
  scroll-margin-top: 4.1rem;
}

.episode-replica-asset-section.is-active {
  display: block;
}

/* Final right quick-lane thumbnail rules */
.episode-replica-right-list {
  display: grid;
  grid-template-columns: 1fr;
  grid-auto-rows: max-content;
  align-content: start;
  gap: 0.48rem;
  overflow: auto;
}

.episode-replica-quick-asset {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1;
  min-height: 0;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 0.82rem;
  background: #202023;
  color: #fff;
  overflow: hidden;
  text-align: left;
}

.episode-replica-quick-asset-trigger {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.episode-replica-quick-asset.active {
  border-color: rgba(147, 216, 255, 0.88);
  box-shadow: 0 0 0 1px rgba(147, 216, 255, 0.18);
}

.episode-replica-quick-asset .thumb {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
  aspect-ratio: auto;
  border-radius: inherit;
  background: #2f3032;
  overflow: hidden;
}

.episode-replica-quick-asset.empty-preview .thumb {
  background: transparent;
}

.episode-replica-quick-thumb-image {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  min-width: 100%;
  min-height: 100%;
  object-fit: cover;
  object-position: center;
  border-radius: inherit;
}

.episode-replica-quick-empty-thumb {
  display: block;
  width: 100%;
  height: 100%;
  background: transparent;
}

.episode-replica-quick-name {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 2;
