  content: "";
  position: absolute;
  inset: -35%;
  background: conic-gradient(from 0deg, transparent, rgba(245, 220, 255, 0.55), transparent 34%);
  animation: asset-generating-orbit 2.2s linear infinite;
}

.asset-generating-placeholder::after {
  content: "";
  position: absolute;
  inset: 0.42rem;
  border-radius: 0.65rem;
  background: #151720;
}

.asset-generating-placeholder span {
  position: absolute;
  z-index: 1;
  width: 58%;
  height: 0.55rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  animation: asset-generating-pulse 1.45s ease-in-out infinite;
}

.asset-generating-placeholder span:nth-child(1) {
  --asset-generating-y: -1.05rem;
  transform: translateY(var(--asset-generating-y));
}

.asset-generating-placeholder span:nth-child(2) {
  width: 44%;
  animation-delay: 0.16s;
}

.asset-generating-placeholder span:nth-child(3) {
  width: 66%;
  --asset-generating-y: 1.05rem;
  transform: translateY(var(--asset-generating-y));
  animation-delay: 0.32s;
}

.asset-generating-placeholder strong {
  position: absolute;
  z-index: 2;
  bottom: 0.9rem;
  color: rgba(255, 255, 255, 0.82);
  font-size: 0.78rem;
  font-weight: 900;
}

@keyframes asset-generating-orbit {
