  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  opacity: 0.72;
}

.workbench-body[data-workbench-theme="daylight"] .original-script-actions .primary-action {
  border-color: rgba(42, 151, 224, 0.28);
  background: var(--theme-accent-gradient);
  color: #145d93;
  box-shadow:
    0 0.75rem 1.6rem rgba(42, 151, 224, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.82);
}

.workbench-body[data-workbench-theme="daylight"] .original-script-actions .primary-action:disabled {
  border-color: rgba(42, 151, 224, 0.18);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.45), rgba(255, 255, 255, 0.12)),
    var(--theme-control-active-background);
  color: color-mix(in srgb, #145d93 62%, transparent);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 0.6rem 1.2rem rgba(42, 151, 224, 0.08);
  opacity: 0.88;
}

/* Unified task center */
.task-center-action {
  position: relative;
}

.task-center-action-count {
  display: inline-grid;
  place-items: center;
  min-width: 1.3rem;
  height: 1.3rem;
  padding: 0 0.32rem;
  border-radius: 0.65rem;
  background: #efb84f;
  color: #221707;
  font-size: 0.68rem;
  font-weight: 850;
  line-height: 1;
}

.task-center-backdrop {
  position: fixed;
  inset: 0;
  z-index: 60;
  background: rgba(2, 5, 9, 0.72);
  backdrop-filter: blur(8px);
}

.task-center-drawer {
  --task-center-border: rgba(255, 255, 255, 0.09);
  --task-center-muted: rgba(224, 232, 240, 0.58);
  --task-center-surface: #10151b;
  --task-center-surface-raised: #171d24;
  position: fixed;
  inset: 1rem;
  z-index: 61;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  width: auto;
  max-width: 92rem;
  margin-left: auto;
  overflow: hidden;
  border: 1px solid var(--task-center-border);
  border-radius: 8px;
  background: #0b0f14;
  color: #f2f5f7;
  box-shadow: 0 2rem 5rem rgba(0, 0, 0, 0.55);
}

.task-center-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 4.5rem;
  padding: 0.85rem 1.15rem;
  border-bottom: 1px solid var(--task-center-border);
  background: #0d1217;
}

.task-center-heading,
.task-center-header-actions,
.task-center-heading > div,
.task-center-id-line,
.task-center-detail-header,
.task-center-pagination,
.task-center-pagination > div {
  display: flex;
  align-items: center;
}

.task-center-heading {
  gap: 0.78rem;
  min-width: 0;
}

.task-center-heading > div {
  align-items: flex-start;
  flex-direction: column;
  gap: 0.12rem;
}

.task-center-heading-icon {
  display: inline-grid;
  place-items: center;
  width: 2.4rem;
  height: 2.4rem;
  border: 1px solid rgba(96, 196, 158, 0.28);
  border-radius: 6px;
  background: rgba(64, 168, 128, 0.1);
  color: #72d6ad;
}

.task-center-heading-icon svg,
.task-center-icon-button svg {
  width: 1.15rem;
  height: 1.15rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.task-center-heading h2,
.task-center-detail h3 {
  margin: 0;
  letter-spacing: 0;
}

.task-center-heading h2 {
  font-size: 1.12rem;
}

.task-center-heading span,
.task-center-detail-header span:first-child {
  color: var(--task-center-muted);
  font-size: 0.75rem;
}

.task-center-header-actions {
  gap: 0.45rem;
}

.task-center-icon-button {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  width: 2.25rem;
  height: 2.25rem;
  padding: 0;
  border: 1px solid var(--task-center-border);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.035);
  color: rgba(239, 244, 248, 0.76);
  cursor: pointer;
}

.task-center-icon-button:hover,
.task-center-icon-button:focus-visible {
  border-color: rgba(114, 214, 173, 0.42);
  background: rgba(114, 214, 173, 0.08);
  color: #8fe1bf;
}

.task-center-icon-button:disabled {
  cursor: wait;
  opacity: 0.42;
}

.task-center-refresh:disabled svg {
  animation: task-center-spin 900ms linear infinite;
}

@keyframes task-center-spin {
  to { transform: rotate(360deg); }
}

.task-center-toolbar {
  display: grid;
  grid-template-columns: auto auto minmax(15rem, 1fr);
  align-items: center;
  gap: 0.75rem;
  padding: 0.78rem 1rem;
  border-bottom: 1px solid var(--task-center-border);
  background: #10151b;
}

.task-center-segments,
.task-center-kind-filter {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--task-center-border);
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.2);
}

.task-center-segments button,
.task-center-kind-filter button,
.task-center-search button,
.task-center-pagination button {
  min-height: 2rem;
  padding: 0.35rem 0.7rem;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--task-center-muted);
  font: inherit;
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
}

.task-center-segments button.active,
.task-center-kind-filter button.active {
  background: #29333d;
  color: #fff;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06);
}

.task-center-search {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  justify-self: end;
  width: min(23rem, 100%);
  min-width: 0;
  border: 1px solid var(--task-center-border);
  border-radius: 6px;
  overflow: hidden;
  background: rgba(0, 0, 0, 0.18);
}

.task-center-search:focus-within {
  border-color: rgba(114, 214, 173, 0.48);
}

.task-center-search input {
  min-width: 0;
  height: 2.25rem;
  padding: 0 0.7rem;
  border: 0;
  outline: 0;
  background: transparent;
  color: #eef4f6;
  font: inherit;
  font-size: 0.8rem;
}

.task-center-search button {
  border-left: 1px solid var(--task-center-border);
  border-radius: 0;
  color: #8fe1bf;
}

.task-center-error {
  position: absolute;
  top: 8.5rem;
  right: 1rem;
  z-index: 2;
  max-width: min(30rem, calc(100% - 2rem));
  padding: 0.65rem 0.8rem;
  border: 1px solid rgba(238, 105, 105, 0.3);
  border-radius: 6px;
  background: #32191b;
  color: #ffb1b1;
  font-size: 0.8rem;
}

.task-center-workspace {
  display: grid;
  grid-template-columns: minmax(32rem, 1.35fr) minmax(23rem, 0.85fr);
  min-height: 0;
}

.task-center-list-pane {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  min-width: 0;
  min-height: 0;
  border-right: 1px solid var(--task-center-border);
}

.task-center-list-head,
.task-center-row {
  display: grid;
  grid-template-columns: minmax(15rem, 1fr) 6.4rem 7.5rem;
  align-items: center;
  gap: 0.75rem;
}

.task-center-list-head {
  min-height: 2.5rem;
  padding: 0 1rem;
  border-bottom: 1px solid var(--task-center-border);
  color: var(--task-center-muted);
  font-size: 0.7rem;
  font-weight: 750;
}

.task-center-list {
  min-height: 0;
  overflow: auto;
  scrollbar-color: #39434d transparent;
}

.task-center-row {
  width: 100%;
  min-height: 4.2rem;
  padding: 0.55rem 1rem;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.055);
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.task-center-row:hover,
.task-center-row:focus-visible {
  background: rgba(255, 255, 255, 0.035);
  outline: 0;
}

.task-center-row.active {
  background: rgba(81, 180, 142, 0.09);
  box-shadow: inset 3px 0 0 #62c99f;
}

.task-center-row-main {
  display: grid;
  grid-template-columns: 2rem minmax(0, 1fr);
  align-items: center;
  gap: 0.65rem;
  min-width: 0;
}

.task-center-kind-mark {
  display: inline-grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border: 1px solid rgba(91, 176, 222, 0.26);
  border-radius: 5px;
  background: rgba(62, 143, 187, 0.11);
  color: #82c9ec;
  font-size: 0.68rem;
  font-weight: 800;
}

.task-center-kind-mark.video {
  border-color: rgba(194, 136, 231, 0.28);
  background: rgba(162, 98, 201, 0.1);
  color: #d3a8ee;
}

.task-center-row-copy {
  display: block;
  min-width: 0;
}

.task-center-row-copy strong,
.task-center-row-copy small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.task-center-row-copy strong {
  color: #eef2f5;
  font-size: 0.82rem;
}

.task-center-row-copy small,
.task-center-row time {
  color: var(--task-center-muted);
  font-size: 0.7rem;
}

.task-center-row-copy small {
  margin-top: 0.3rem;
}

.task-center-status {
  display: inline-flex;
  align-items: center;
  justify-self: start;
  gap: 0.38rem;
  min-width: 0;
  color: #bbc5cd;
  font-size: 0.72rem;
  font-weight: 750;
}

.task-center-status i {
  width: 0.42rem;
  height: 0.42rem;
  flex: 0 0 auto;
  border-radius: 50%;
  background: currentColor;
}

.task-center-status.queued { color: #e5bd65; }
.task-center-status.active { color: #72c9ef; }
.task-center-status.completed { color: #72d6ad; }
.task-center-status.failed { color: #f28a8a; }
.task-center-status.active i { animation: task-center-pulse 1.4s ease-in-out infinite; }

@keyframes task-center-pulse {
  50% { opacity: 0.32; }
}

.task-center-pagination {
  justify-content: space-between;
  min-height: 3.1rem;
  padding: 0.5rem 1rem;
  border-top: 1px solid var(--task-center-border);
  color: var(--task-center-muted);
  font-size: 0.72rem;
}

.task-center-pagination > div { gap: 0.35rem; }

.task-center-pagination button {
  border: 1px solid var(--task-center-border);
  background: rgba(255, 255, 255, 0.025);
}

.task-center-pagination button:disabled {
  cursor: default;
  opacity: 0.35;
}

.task-center-empty,
.task-center-detail-empty {
  display: grid;
  place-content: center;
  gap: 0.35rem;
  min-height: 12rem;
  color: var(--task-center-muted);
  text-align: center;
}

.task-center-empty strong,
.task-center-detail-empty strong {
  color: #dce3e8;
  font-size: 0.86rem;
}

.task-center-empty span { font-size: 0.76rem; }

.task-center-row-skeleton {
  cursor: default;
}

.task-center-row-skeleton span {
  height: 0.75rem;
  border-radius: 3px;
  background: #202830;
  animation: task-center-skeleton 1.2s ease-in-out infinite alternate;
}

@keyframes task-center-skeleton {
  to { opacity: 0.45; }
}

.task-center-detail {
  min-width: 0;
  min-height: 0;
  padding: 1.15rem;
  overflow: auto;
  background: #0d1217;
  scrollbar-color: #39434d transparent;
}

.task-center-detail-header {
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.task-center-detail-header h3 {
  max-width: 24rem;
  margin-top: 0.28rem;
  overflow-wrap: anywhere;
  color: #f3f6f8;
  font-size: 1rem;
}

.task-center-id-line {
  gap: 0.45rem;
  margin-top: 0.85rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--task-center-border);
}

.task-center-id-line code {
  min-width: 0;
  overflow: hidden;
  color: #8e9ba7;
  font-size: 0.7rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.task-center-id-line .task-center-icon-button {
  width: 1.9rem;
  height: 1.9rem;
}

.task-center-result,
.task-center-prompt,
.task-center-failure,
.task-center-metadata {
  margin-top: 1rem;
}

.task-center-section-label {
  display: block;
  margin-bottom: 0.55rem;
  color: var(--task-center-muted);
  font-size: 0.68rem;
  font-weight: 800;
}

.task-center-result img,
.task-center-result video {
  display: block;
  width: 100%;
  max-height: 22rem;
  border: 1px solid var(--task-center-border);
  border-radius: 6px;
  background: #070a0d;
  object-fit: contain;
}

.task-center-result pre,
.task-center-result-empty {
  min-height: 7rem;
  margin: 0;
  padding: 0.8rem;
  border: 1px solid var(--task-center-border);
  border-radius: 6px;
  background: #090d11;
  color: #c8d1d8;
  font: inherit;
  font-size: 0.76rem;
  line-height: 1.65;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.task-center-result-empty {
  display: grid;
  place-items: center;
  color: var(--task-center-muted);
}

.task-center-prompt p,
.task-center-failure p {
  margin: 0;
  padding: 0.72rem;
  border-left: 2px solid #4c8e74;
  background: rgba(255, 255, 255, 0.025);
  color: #bdc7ce;
  font-size: 0.76rem;
  line-height: 1.65;
  overflow-wrap: anywhere;
}

.task-center-failure p {
  border-left-color: #c95f63;
  color: #f1a0a2;
}

.task-center-metadata {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: 1px solid var(--task-center-border);
  border-left: 1px solid var(--task-center-border);
}

.task-center-metadata > div {
  min-width: 0;
  padding: 0.7rem;
  border-right: 1px solid var(--task-center-border);
  border-bottom: 1px solid var(--task-center-border);
}

.task-center-metadata dt {
  color: var(--task-center-muted);
  font-size: 0.66rem;
}

.task-center-metadata dd {
  margin: 0.3rem 0 0;
  color: #dce3e8;
  font-size: 0.74rem;
  overflow-wrap: anywhere;
}

.workbench-body[data-workbench-theme="daylight"] .task-center-backdrop {
  background: rgba(31, 45, 58, 0.32);
}

.workbench-body[data-workbench-theme="daylight"] .task-center-drawer {
  --task-center-border: rgba(37, 63, 82, 0.13);
  --task-center-muted: #687989;
  --task-center-surface: #f3f7f9;
  --task-center-surface-raised: #ffffff;
  background: #f7fafb;
  color: #172331;
  box-shadow: 0 2rem 5rem rgba(34, 61, 79, 0.25);
}

.workbench-body[data-workbench-theme="daylight"] .task-center-header,
.workbench-body[data-workbench-theme="daylight"] .task-center-detail {
  background: #ffffff;
}

.workbench-body[data-workbench-theme="daylight"] .task-center-toolbar {
  background: #f0f5f7;
}

.workbench-body[data-workbench-theme="daylight"] .task-center-segments,
.workbench-body[data-workbench-theme="daylight"] .task-center-kind-filter,
.workbench-body[data-workbench-theme="daylight"] .task-center-search {
  background: #ffffff;
}

.workbench-body[data-workbench-theme="daylight"] .task-center-segments button.active,
.workbench-body[data-workbench-theme="daylight"] .task-center-kind-filter button.active {
  background: #dfe9ed;
  color: #172b38;
}

.workbench-body[data-workbench-theme="daylight"] .task-center-search input,
.workbench-body[data-workbench-theme="daylight"] .task-center-row-copy strong,
.workbench-body[data-workbench-theme="daylight"] .task-center-detail-header h3,
.workbench-body[data-workbench-theme="daylight"] .task-center-empty strong,
.workbench-body[data-workbench-theme="daylight"] .task-center-detail-empty strong,
.workbench-body[data-workbench-theme="daylight"] .task-center-metadata dd {
  color: #172b38;
}

.workbench-body[data-workbench-theme="daylight"] .task-center-row:hover,
.workbench-body[data-workbench-theme="daylight"] .task-center-row:focus-visible {
  background: rgba(43, 90, 115, 0.045);
}

.workbench-body[data-workbench-theme="daylight"] .task-center-row.active {
  background: rgba(42, 151, 118, 0.09);
}

.workbench-body[data-workbench-theme="daylight"] .task-center-result pre,
.workbench-body[data-workbench-theme="daylight"] .task-center-result-empty,
.workbench-body[data-workbench-theme="daylight"] .task-center-prompt p {
  background: #f4f7f8;
  color: #415362;
}

@media (max-width: 1120px) {
  .task-center-toolbar {
    grid-template-columns: 1fr 1fr;
  }

  .task-center-search {
    grid-column: 1 / -1;
    justify-self: stretch;
    width: 100%;
  }

  .task-center-workspace {
    grid-template-columns: minmax(27rem, 1.15fr) minmax(20rem, 0.85fr);
  }
}

@media (max-width: 820px) {
  .task-center-drawer {
    inset: 0;
    border: 0;
    border-radius: 0;
  }

  .task-center-toolbar {
    grid-template-columns: 1fr;
    overflow-x: auto;
  }

  .task-center-segments,
  .task-center-kind-filter {
    width: max-content;
    max-width: none;
  }

  .task-center-search { grid-column: auto; }

  .task-center-workspace {
    display: block;
    overflow: auto;
  }

  .task-center-list-pane {
    min-height: 24rem;
    border-right: 0;
    border-bottom: 1px solid var(--task-center-border);
  }

  .task-center-list { max-height: 32rem; }
  .task-center-detail { min-height: 28rem; overflow: visible; }
}

@media (max-width: 560px) {
  .task-center-header { min-height: 4rem; padding: 0.7rem 0.8rem; }
  .task-center-toolbar { padding: 0.65rem 0.75rem; }
  .task-center-list-head { display: none; }

  .task-center-row {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 0.45rem;
    min-height: 4.6rem;
    padding: 0.6rem 0.75rem;
  }

  .task-center-row time {
    grid-column: 1 / -1;
    padding-left: 2.65rem;
  }

  .task-center-metadata { grid-template-columns: 1fr; }
  .task-center-detail { padding: 0.9rem; }
  .task-center-heading > div > span { display: none; }
}

/* Keep episode navigation aligned with the global menu controls. */
.workbench-body .statusbar-episode-return {
  flex: 0 0 auto;
}

.workbench-body .statusbar-episode-center {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 1;
  transform: translate(-50%, -50%);
}

.workbench-body .episode-statusbar-return,
.workbench-body .episode-replica-asset-scope-jump,
.workbench-body .episode-replica-storyboard-scope-jump {
  border: 1px solid var(--theme-statusbar-border);
  background: var(--theme-statusbar-button-background);
  color: rgba(255, 255, 255, 0.94);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 0.45rem 1rem rgba(0, 0, 0, 0.18);
  animation: none;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    background 160ms ease,
    box-shadow 160ms ease;
}

.workbench-body .episode-statusbar-return:hover,
.workbench-body .episode-statusbar-return:focus-visible,
.workbench-body .episode-replica-asset-scope-jump:hover,
.workbench-body .episode-replica-asset-scope-jump:focus-visible,
.workbench-body .episode-replica-storyboard-scope-jump:hover,
.workbench-body .episode-replica-storyboard-scope-jump:focus-visible {
  border-color: var(--theme-statusbar-hover-border);
  background: var(--theme-statusbar-button-hover-background);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 0.55rem 1.2rem var(--theme-statusbar-shadow);
  transform: translateY(-1px);
}

.workbench-body .episode-statusbar-return {
  min-width: 8.8rem;
  min-height: 2.9rem;
  padding: 0 1rem;
  border-radius: 0.9rem;
  font-size: 1rem;
}

.workbench-body .episode-statusbar-return span {
  font-size: 1.08rem;
}

.workbench-body .episode-statusbar-return strong {
  font-size: 1rem;
  font-weight: 800;
}

.workbench-body .episode-replica-asset-scope-jump,
.workbench-body .episode-replica-storyboard-scope-jump {
  min-height: 2.9rem;
  border-radius: 0.9rem;
}

.workbench-body[data-workbench-theme="daylight"] .episode-statusbar-return,
.workbench-body[data-workbench-theme="daylight"] .episode-replica-asset-scope-jump,
.workbench-body[data-workbench-theme="daylight"] .episode-replica-storyboard-scope-jump {
  color: #36536c;
}

.workbench-body[data-workbench-theme="daylight"] .episode-statusbar-return:hover,
.workbench-body[data-workbench-theme="daylight"] .episode-statusbar-return:focus-visible,
.workbench-body[data-workbench-theme="daylight"] .episode-replica-asset-scope-jump:hover,
.workbench-body[data-workbench-theme="daylight"] .episode-replica-asset-scope-jump:focus-visible,
.workbench-body[data-workbench-theme="daylight"] .episode-replica-storyboard-scope-jump:hover,
.workbench-body[data-workbench-theme="daylight"] .episode-replica-storyboard-scope-jump:focus-visible {
  color: #102033;
}

.workbench-body .episode-replica-stage-tabs .episode-replica-batch-actions {
  flex-wrap: nowrap;
  gap: 0.35rem;
  margin-left: auto;
}

.workbench-body .episode-replica-storyboard-toolbar .episode-replica-export {
  width: auto;
  min-width: 0;
  border: 1px solid var(--theme-control-border);
  background: var(--theme-control-background);
  color: rgba(255, 255, 255, 0.92);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.055),
    0 0.55rem 1.2rem rgba(0, 0, 0, 0.15);
}

.workbench-body .episode-replica-storyboard-toolbar .episode-replica-export:hover,
.workbench-body .episode-replica-storyboard-toolbar .episode-replica-export:focus-visible {
  border-color: var(--theme-control-hover-border);
  background: var(--theme-control-hover-background);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.075),
    0 0.9rem 1.8rem var(--theme-accent-soft);
}

.workbench-body[data-workbench-theme="daylight"] .episode-replica-storyboard-toolbar .episode-replica-export {
  color: #36536c;
}

.workbench-body[data-workbench-theme="daylight"] .episode-replica-storyboard-toolbar .episode-replica-export:hover,
.workbench-body[data-workbench-theme="daylight"] .episode-replica-storyboard-toolbar .episode-replica-export:focus-visible {
  color: #102033;
}

/* Structured prompt editor */
.episode-prompt-editor-host {
  box-sizing: border-box;
  width: 100%;
  min-height: clamp(7.5rem, 16vh, 10.5rem);
  height: clamp(7.5rem, 16vh, 10.5rem);
  overflow-x: hidden;
  overflow-y: auto;
  border: 0;
  border-radius: 1rem;
  background: #242424;
  color: #f5f5f5;
  scrollbar-color: rgba(255, 255, 255, 0.24) transparent;
  scrollbar-width: thin;
}

.episode-prompt-editor-host:focus-within {
  box-shadow: inset 0 0 0 1px rgba(145, 214, 255, 0.42);
}

.episode-prompt-editor-content {
  box-sizing: border-box;
  min-height: 100%;
  padding: 1.2rem 1rem 3rem;
  outline: none;
  color: inherit;
  font: inherit;
  font-size: 0.92rem;
  font-weight: 800;
  line-height: 1.55;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.episode-prompt-editor-content p {
  min-height: 1.45em;
  margin: 0;
}

.episode-prompt-editor-content p + p {
  margin-top: 0.08rem;
}

.episode-prompt-editor-content p.is-editor-empty:first-child::before {
  height: 0;
  float: left;
  color: rgba(173, 183, 198, 0.64);
  content: attr(data-placeholder);
  font-weight: 700;
  pointer-events: none;
}

.episode-prompt-editor-mention {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  max-width: min(12rem, 70%);
  height: 1.7rem;
  min-height: 1.7rem;
  max-height: 1.7rem;
  gap: 0.34rem;
  margin: 0 0.08rem;
  padding: 0.1rem 0.48rem 0.1rem 0.16rem;
  overflow: hidden;
  line-height: 1;
  vertical-align: middle;
  border: 1px solid rgba(145, 214, 255, 0.34);
  border-radius: 0.42rem;
  background: rgba(145, 214, 255, 0.11);
  color: #c9ecff;
  cursor: default;
  user-select: all;
}

.episode-prompt-editor-mention img,
.episode-prompt-editor-mention video,
.episode-prompt-editor-mention-fallback {
  box-sizing: border-box;
  display: grid;
  width: 1.26rem;
  height: 1.26rem;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.14);
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.68rem;
  object-fit: cover;
}

.episode-prompt-editor-mention video {
  pointer-events: none;
}

.episode-prompt-editor-mention-label {
  min-width: 0;
  overflow: hidden;
  font-size: 0.78rem;
  font-weight: 900;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.episode-prompt-editor-menu {
  z-index: 1000;
  display: grid;
  gap: 0.2rem;
  width: 13rem;
  max-width: calc(100vw - 1.5rem);
  max-height: min(16rem, calc(100vh - 1.5rem));
  padding: 0.3rem;
  overflow-y: auto;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 0.5rem;
  background: rgba(25, 27, 32, 0.98);
  box-shadow: 0 0.7rem 1.8rem rgba(0, 0, 0, 0.42);
  scrollbar-color: rgba(255, 255, 255, 0.22) transparent;
  scrollbar-width: thin;
}

.episode-prompt-editor-menu[hidden] {
  display: none;
}

.episode-prompt-editor-option {
  display: grid;
  grid-template-columns: 2rem minmax(0, 1fr);
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  min-height: 2.45rem;
  padding: 0.22rem 0.5rem 0.22rem 0.24rem;
  border: 1px solid transparent;
  border-radius: 0.36rem;
  background: rgba(255, 255, 255, 0.035);
  color: rgba(255, 255, 255, 0.92);
  text-align: left;
}

.episode-prompt-editor-option:hover,
.episode-prompt-editor-option.is-active {
  border-color: rgba(145, 214, 255, 0.22);
  background: rgba(145, 214, 255, 0.12);
}

.episode-prompt-editor-option-thumb {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  overflow: hidden;
  border-radius: 999px;
  background: #353840;
  color: rgba(255, 255, 255, 0.88);
  font-size: 0.74rem;
  font-weight: 900;
}

.episode-prompt-editor-option-thumb img,
.episode-prompt-editor-option-thumb video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.episode-prompt-editor-option-copy {
  display: grid;
  min-width: 0;
  gap: 0.08rem;
}

.episode-prompt-editor-option-copy strong,
.episode-prompt-editor-option-copy small {
  overflow: hidden;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.episode-prompt-editor-option-copy strong {
  font-size: 0.8rem;
}

.episode-prompt-editor-option-copy small {
  color: rgba(255, 255, 255, 0.55);
  font-size: 0.66rem;
}

.episode-replica-textarea.has-inline-attachments .episode-prompt-editor-host {
  min-height: 0;
  height: 100%;
  border-radius: 0;
  background: transparent;
}

.episode-replica-textarea.has-inline-attachments .episode-prompt-editor-content {
  padding-top: 0.55rem;
}

.episode-replica-textarea em[data-prompt-character-count] {
  z-index: 4;
  pointer-events: none;
}

.workbench-body[data-workbench-theme="daylight"] .episode-prompt-editor-host {
  border-color: rgba(28, 92, 139, 0.13);
  background: rgba(255, 255, 255, 0.88);
  color: #162033;
}

.workbench-body[data-workbench-theme="daylight"] .episode-replica-textarea.has-inline-attachments,
.workbench-body[data-workbench-theme="daylight"] .episode-replica-textarea.has-inline-attachments .episode-prompt-editor-host {
  background: rgba(255, 255, 255, 0.88);
}

.workbench-body[data-workbench-theme="daylight"] .episode-prompt-editor-mention {
  border-color: rgba(28, 92, 139, 0.24);
  background: rgba(28, 92, 139, 0.09);
  color: #145d93;
}

@media (min-width: 961px) {
  .episode-prompt-editor-host {
    height: 100%;
    min-height: 7.8rem;
    max-height: none;
  }

  .episode-replica-layout.storyboard-mode .episode-prompt-editor-host {
    min-height: 5.8rem;
  }

  .episode-replica-layout.storyboard-mode .episode-replica-prompt.video-mode .episode-prompt-editor-host {
    min-height: 0;
    max-height: 100%;
  }

  .episode-workbench-screen .episode-replica-layout.assets-mode > .episode-replica-center.asset-scope .episode-prompt-editor-host {
    height: 8.2rem !important;
    min-height: 8.2rem !important;
    max-height: 8.2rem !important;
  }
}

@media (min-width: 961px) and (max-height: 820px) {
  .episode-replica-layout.storyboard-mode .episode-prompt-editor-host {
    min-height: 4.9rem;
  }

  .episode-replica-layout.storyboard-mode .episode-replica-prompt.video-mode .episode-prompt-editor-host {
    min-height: 0;
    max-height: 100%;
  }
}
